-- ============================================================
-- 0045 — Curadoria dos textos-base da RNC: Edificações (ED)
-- Gerado da curadoria multi-agente (draft + verificação normativa).
-- Um UPDATE por item: gravidade + fundamentação + risco + ação específicos.
-- Escrita restrita a super_admin (tabela de plataforma).
-- ============================================================

-- ED-01 (8 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se o lote não conforme já houver sido assentado nos panos ou se a divergência de resistência/classe comprometer a estabilidade ou o desempenho da vedação',
  texto_fundamentacao_normativa = 'Os blocos devem ser recebidos, inspecionados e liberados em conformidade com o tipo, a classe de resistência e o lote definidos na especificação técnica e no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Conforme o material empregado, aplicam-se a NBR 15270 (componentes cerâmicos para alvenaria) ou a NBR 6136 (blocos vazados de concreto para alvenaria), que estabelecem dimensões, resistência à compressão e requisitos de aceitação do lote. O critério "Tipo, resistência e lote conferidos no recebimento" integra o plano de inspeção de recebimento de materiais e constitui requisito verificável de aceitação, cabendo conferência da nota fiscal, do certificado do fabricante e da amostragem física do lote.',
  texto_risco_consequencia = 'Blocos fora da especificação incorporados à obra comprometem a resistência, a planeza e a estabilidade dos panos de alvenaria, com risco de fissuração, deformação e retrabalho de demolição e reconstrução, além de rastreabilidade deficiente do lote em caso de patologia futura. A permanência da condição mantém material não conforme na estrutura de vedação até a efetiva segregação e substituição. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) segregar e identificar o lote não conforme, impedindo seu uso e confrontando tipo, classe de resistência e dimensões com a especificação e a documentação de recebimento; (ii) substituir por material conforme, com certificado do fabricante e, quando exigível, ensaio de amostragem do lote; (iii) evidenciar a correção com registro fotográfico do material liberado e da documentação de rastreabilidade ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-01' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se o desvio de marcação da primeira fiada se propagar aos pavimentos superiores ou comprometer o esquadro de ambientes e o assentamento de esquadrias',
  texto_fundamentacao_normativa = 'A marcação e a primeira fiada devem ser executadas a partir dos eixos topográficos, garantindo esquadro, alinhamento e nível de referência para todo o pano, conforme o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. A NBR 8545 (execução de alvenaria sem função estrutural) orienta a marcação e o assentamento da fiada de arranque como etapa determinante da geometria da vedação. O critério "Esquadro e alinhamento a partir de eixos topográficos" integra o plano de inspeção da obra e constitui requisito verificável de aceitação, uma vez que a primeira fiada define a referência de prumo e alinhamento das fiadas subsequentes.',
  texto_risco_consequencia = 'Marcação e primeira fiada executadas fora de esquadro ou desalinhadas dos eixos topográficos propagam o erro geométrico a todo o pano e aos pavimentos superiores, comprometendo o assentamento de esquadrias, revestimentos e o esquadro dos ambientes, com necessidade de encunhamentos e regularizações excessivas ou retrabalho de demolição. A permanência da condição mantém a referência geométrica incorreta até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reconferir os eixos topográficos e reposicionar a marcação, verificando esquadro, alinhamento e nível de arranque; (ii) refazer a primeira fiada quando o desvio exceder as tolerâncias, restabelecendo a referência correta antes do prosseguimento da elevação; (iii) evidenciar a correção com registro fotográfico e conferência instrumental ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-01' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando o desvio de prumo ou alinhamento exceder as tolerâncias em painéis extensos, de grande altura ou que receberão revestimento aderido de pequena espessura',
  texto_fundamentacao_normativa = 'Os panos de alvenaria devem manter prumo e alinhamento dentro das tolerâncias verificadas por régua e prumo (ou nível a laser) a cada pavimento, conforme o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. A NBR 8545 (execução de alvenaria sem função estrutural) e as boas práticas de execução estabelecem a verificação sistemática de prumo e planicidade como controle da etapa. O critério "Régua/prumo dentro das tolerâncias (verificação por pavimento)" integra o plano de inspeção da obra e constitui requisito verificável de aceitação, dada a influência direta sobre a espessura e o consumo do revestimento posterior.',
  texto_risco_consequencia = 'Panos fora de prumo ou desalinhados obrigam a compensação por espessuras excessivas e irregulares de revestimento, elevando o consumo de argamassa, o risco de fissuração e destacamento do revestimento e o comprometimento estético e funcional da vedação, podendo exigir demolição parcial. A permanência da condição mantém o desvio geométrico do pano até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reverificar prumo e alinhamento do pano com régua e prumo (ou nível a laser), mapeando os trechos fora de tolerância; (ii) corrigir os trechos divergentes por reassentamento das fiadas afetadas, evitando o mascaramento por revestimento espesso; (iii) evidenciar a correção com registro fotográfico e nova verificação instrumental ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-01' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a ausência de amarração entre panos ou com a estrutura comprometer a estabilidade do painel de vedação a solicitações horizontais',
  texto_fundamentacao_normativa = 'A amarração entre panos e a ligação da alvenaria com a estrutura, além da defasagem das juntas verticais entre fiadas, devem seguir o detalhamento do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. A NBR 8545 (execução de alvenaria sem função estrutural) trata da amarração das fiadas e da ligação do pano aos pilares e vigas por telas, ferros-cabelo ou juntas amarradas. O critério "Amarração entre panos e com estrutura conforme projeto" integra o plano de inspeção da obra e constitui requisito verificável de aceitação, pois a defasagem de juntas e a ancoragem à estrutura asseguram o monolitismo e a estabilidade da vedação.',
  texto_risco_consequencia = 'A ausência de amarração adequada e de defasagem das juntas cria planos preferenciais de fissuração e reduz a capacidade do pano de resistir a esforços horizontais e a movimentações da estrutura, com risco de fissuras verticais contínuas, destacamento do pano e, em situações limite, colapso parcial da vedação. A permanência da condição mantém o painel sem a ligação estrutural prevista até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) confrontar a execução com o detalhe de amarração do projeto, identificando panos sem ligação à estrutura e fiadas com juntas coincidentes; (ii) implantar a amarração prevista (telas, ferros-cabelo ou reassentamento com juntas defasadas), restabelecendo a ligação aos pilares e vigas; (iii) evidenciar a correção com registro fotográfico dos elementos de amarração instalados ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-01' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a ausência de verga ou contraverga sobre vãos comprometer a distribuição de esforços e favorecer fissuração em elementos que recebem esquadrias',
  texto_fundamentacao_normativa = 'Todos os vãos de portas e janelas devem receber vergas e, nas janelas, contravergas, com transpasse (apoio) mínimo sobre a alvenaria de cada lado, conforme o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. A NBR 8545 (execução de alvenaria sem função estrutural) e as boas práticas construtivas estabelecem a execução de vergas e contravergas como dispositivo de redistribuição das tensões nos cantos dos vãos. O critério "Em todos os vãos, com apoios mínimos" integra o plano de inspeção da obra e constitui requisito verificável de aceitação, cabendo conferência da existência do elemento e do comprimento de apoio de cada extremidade.',
  texto_risco_consequencia = 'A ausência de vergas ou contravergas, ou o apoio insuficiente sobre a alvenaria, concentra tensões nos cantos dos vãos e origina fissuras inclinadas típicas a 45°, com comprometimento da vedação, infiltração e destacamento de revestimento, exigindo tratamento de fissuras ou demolição e refazimento do trecho. A permanência da condição mantém o vão sem o reforço previsto até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) levantar todos os vãos, identificando ausência de verga/contraverga ou apoio inferior ao mínimo especificado; (ii) executar as vergas e contravergas faltantes com o transpasse de projeto sobre a alvenaria de ambos os lados, demolindo o trecho apenas quando necessário à sua inserção; (iii) evidenciar a correção com registro fotográfico dos elementos executados e da medição dos apoios ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-01' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o encunhamento for executado antes da acomodação/deformação da estrutura ou com material inadequado, favorecendo fissuras na interface alvenaria-viga',
  texto_fundamentacao_normativa = 'A fixação superior (encunhamento) do pano à estrutura deve empregar o material especificado e ser executada somente após o prazo de acomodação e a deformação prevista da estrutura, conforme o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. A NBR 8545 (execução de alvenaria sem função estrutural) e as boas práticas de execução condicionam o encunhamento à idade da estrutura e ao emprego de material com capacidade de acomodar deformações. O critério "Material e prazo conforme projeto (após deformação da estrutura)" integra o plano de inspeção da obra e constitui requisito verificável de aceitação, cabendo conferência do intervalo mínimo decorrido e do material aplicado.',
  texto_risco_consequencia = 'Encunhamento executado precocemente ou com material inadequado transfere ao pano as deformações da estrutura sobrejacente, gerando fissuras horizontais na interface alvenaria-viga, destacamento de revestimento e infiltração, com necessidade de retratamento recorrente da junta. A permanência da condição mantém a fixação superior deficiente até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) verificar o prazo decorrido desde a concretagem/carregamento da estrutura e o material de encunhamento empregado, confrontando com a especificação; (ii) refazer o encunhamento dos trechos executados precocemente ou com material inadequado, respeitando o intervalo e o material previstos; (iii) evidenciar a correção com registro fotográfico da fixação superior refeita ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-01' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando rasgos horizontais contínuos ou de profundidade excessiva enfraquecerem o pano ou houver incompatibilidade não resolvida com as instalações',
  texto_fundamentacao_normativa = 'Os embutimentos de instalações devem ser coordenados e compatibilizados entre os projetos, com rasgos limitados em extensão, profundidade e orientação, conforme o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}} e a compatibilização das disciplinas de instalações. A NBR 8545 (execução de alvenaria sem função estrutural) e as boas práticas de execução restringem a abertura de rasgos que reduzam a seção resistente do pano, privilegiando passagens previstas em projeto. O critério "Rasgos limitados; passagens compatibilizadas com instalações" integra o plano de inspeção da obra e constitui requisito verificável de aceitação, cabendo conferência da conformidade dos rasgos com o detalhamento e da compatibilidade com o traçado das instalações.',
  texto_risco_consequencia = 'Rasgos excessivos, horizontais contínuos ou não compatibilizados enfraquecem o pano de alvenaria e concentram tensões, favorecendo fissuração ao longo do embutimento, além de conflitos entre instalações que exigem retrabalho de reabertura e novo fechamento. A permanência da condição mantém o pano com rasgos indevidos e passagens não coordenadas até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) mapear os rasgos e embutimentos executados, confrontando com os projetos de instalações e o detalhamento de passagens; (ii) recompor os rasgos indevidos com material adequado e telas de reforço quando aplicável, redirecionando as passagens para o traçado compatibilizado; (iii) evidenciar a correção com registro fotográfico dos embutimentos coordenados e recompostos ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-01' and item_numero = 7;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o traço ou a argamassa industrializada empregada não atender à especificação e comprometer a aderência e a resistência das juntas de assentamento',
  texto_fundamentacao_normativa = 'A argamassa de assentamento deve reproduzir o traço ou a argamassa industrializada definidos na especificação técnica e no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, com controle da dosagem, do preparo e do prazo de utilização. A NBR 13281 (requisitos de argamassas para assentamento e revestimento) e as boas práticas de execução estabelecem parâmetros de resistência, aderência e trabalhabilidade das argamassas. O critério "Traço/industrializada conforme especificação" integra o plano de inspeção da obra e constitui requisito verificável de aceitação, cabendo conferência da dosagem, da identificação do produto industrializado e do preparo em obra.',
  texto_risco_consequencia = 'Argamassa de assentamento fora do traço ou da especificação reduz a aderência e a resistência das juntas, favorecendo destacamento entre fiadas, fissuração e comprometimento da estabilidade e da estanqueidade do pano, com risco de retrabalho de reassentamento. A permanência da condição mantém juntas com argamassa não conforme ao longo do pano até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) suspender o assentamento com a argamassa não conforme e reconferir o traço ou a argamassa industrializada frente à especificação, verificando dosagem, validade e preparo; (ii) restabelecer o preparo conforme especificado e reassentar os trechos executados com argamassa inadequada quando a aderência estiver comprometida; (iii) evidenciar a correção com registro fotográfico do preparo e das juntas executadas ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-01' and item_numero = 8;

-- ED-02 (7 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o sistema aplicado for incompatível com a solicitação da área (áreas frias, molháveis, submersas ou de grande movimentação) ou quando divergir da manta/membrana especificada em projeto.',
  texto_fundamentacao_normativa = 'A seleção do sistema de impermeabilização deve corresponder à exigência de cada área (percentual de exposição à água, movimentação estrutural e trânsito), condição definida em projeto específico. Aplicam-se a NBR 9575 (impermeabilização — seleção e projeto), referida no próprio critério do item, e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que definem o tipo de manta/membrana por área. A verificação do sistema efetivamente empregado frente ao projeto integra o plano de inspeção e constitui requisito de aceitação da etapa.',
  texto_risco_consequencia = 'A adoção de sistema diverso do projeto pode resultar em impermeabilização subdimensionada para a solicitação da área, com falha precoce, infiltrações e comprometimento de estruturas e acabamentos subjacentes, exigindo remoção do recobrimento e refazimento integral, com sobrecusto e atraso. A permanência da condição mantém o desvio de especificação ativo até a correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) confrontar o sistema aplicado com a especificação de projeto por área, identificando as regiões em desacordo; (ii) substituir ou complementar o sistema de forma a atender ao tipo de manta/membrana previsto para cada área; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e ficha técnica do material efetivamente empregado, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-02' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se o substrato apresentar caimento invertido, empoçamento, umidade excessiva ou contaminação que inviabilize a aderência do sistema.',
  texto_fundamentacao_normativa = 'O substrato deve estar regularizado com caimento adequado ao escoamento (tipicamente em direção aos ralos), limpo, seco/curado e isento de partículas soltas, arestas vivas e ninhos, condição imprescindível à aderência e ao desempenho do sistema. Aplicam-se a NBR 9574 (execução de impermeabilização), o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}} e as recomendações do fabricante quanto ao preparo da base. O critério de regularização, limpeza e cura integra o plano de inspeção como requisito verificável de liberação para a aplicação.',
  texto_risco_consequencia = 'Substrato mal regularizado, contaminado ou com caimento deficiente compromete a aderência do sistema e favorece o empoçamento, descolamento e formação de bolhas, levando à falha da impermeabilização e a infiltrações, com necessidade de remoção e refazimento. A permanência da condição mantém a base inadequada até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reconferir o caimento com nível/mangueira e a limpeza do substrato, mapeando pontos de empoçamento, arestas vivas e contaminação; (ii) refazer a regularização com argamassa de caimento, arredondar cantos e cantos vivos e garantir a cura e a secagem antes da aplicação; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e teste de caimento, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-02' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — os detalhes de ralos, tubos emergentes, cantos e subida em paredes são os pontos preferenciais de falha; manter Maior apenas se o desvio for isolado e prontamente sanável antes do recobrimento.',
  texto_fundamentacao_normativa = 'Os detalhes construtivos — reforço em ralos e tubos emergentes, arredondamento e reforço de cantos e rodapés, e subida da impermeabilização de no mínimo 30 cm nas paredes — são requisitos de estanqueidade nas transições e emboques, onde a lâmina d''água tende a concentrar solicitação. Aplicam-se a NBR 9574 (execução de impermeabilização), o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}} e as recomendações do fabricante para arremates. O critério dos detalhes críticos integra o plano de inspeção como requisito de aceitação da etapa.',
  texto_risco_consequencia = 'A ausência de reforço em ralos, tubos emergentes e cantos, ou subida em parede inferior a 30 cm, cria caminhos preferenciais de infiltração justamente nos pontos mais solicitados, resultando em vazamentos localizados, deterioração de estruturas e acabamentos e retrabalho de difícil acesso após o recobrimento. A permanência da condição mantém os pontos críticos desprotegidos até a correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) inspecionar cada ralo, tubo emergente e canto, medindo a altura de subida nas paredes e confrontando com o mínimo de 30 cm e com o projeto; (ii) executar os reforços e arremates faltantes (reforço em ralos e emboques, tela/reforço em cantos e prolongamento da subida), conforme detalhe de projeto e fabricante; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) detalhando cada ponto tratado, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-02' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o consumo/nº de demãos aplicado ficar abaixo do mínimo do fabricante ou não houver registro que comprove a espessura final especificada.',
  texto_fundamentacao_normativa = 'O consumo por metro quadrado, a espessura final e o número de demãos devem atender ao especificado pelo fabricante, com registro que permita a rastreabilidade da aplicação, pois deles depende a formação de película contínua e estanque. Fundamenta-se pelas recomendações técnicas do fabricante do sistema, pela NBR 9574 (execução de impermeabilização) e pelo projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério de registro de espessura e demãos integra o plano de inspeção como requisito verificável da etapa.',
  texto_risco_consequencia = 'Consumo abaixo do especificado ou número insuficiente de demãos resulta em película de espessura inferior à de projeto, com pontos frágeis, perda precoce de estanqueidade e infiltrações, além de impossibilitar a comprovação técnica da aplicação na ausência de registro. A permanência da condição mantém a camada subdimensionada até a correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) confrontar o consumo real e o nº de demãos aplicadas com a ficha técnica do fabricante, verificando a espessura por área; (ii) aplicar as demãos complementares necessárias ao atendimento do consumo e da espessura especificados, respeitando os intervalos de cura entre demãos; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e planilha de consumo por área, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-02' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — o teste de estanqueidade é a verificação final que libera o recobrimento; manter Maior apenas quando o teste foi realizado, mas com prazo/registro incompletos e sem evidência de vazamento.',
  texto_fundamentacao_normativa = 'O teste de estanqueidade por lâmina d''água mantida por 72 horas, com registro fotográfico e ata, é o ensaio de aceitação que comprova a integridade do sistema antes de qualquer recobrimento. Aplicam-se a NBR 9574 (execução de impermeabilização), que prevê ensaios de estanqueidade, e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério de lâmina d''água por 72h com registro fotográfico e ata integra o plano de inspeção como requisito de liberação da etapa.',
  texto_risco_consequencia = 'A não realização do teste, ou sua realização sem o período de 72h e sem registro/ata, libera o recobrimento sem comprovação de estanqueidade, permitindo que falhas ocultas só se manifestem em serviço, quando a correção exige remoção de acabamentos e estruturas, com elevado sobrecusto e atraso. A permanência da condição mantém o sistema não comprovado até a realização do ensaio. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) programar e executar a lâmina d''água pelo período mínimo de 72h, com vedação prévia de ralos e demarcação do nível; (ii) monitorar o nível e inspecionar os panos inferiores quanto a manchas/infiltração ao longo do ensaio, tratando eventuais pontos de vazamento antes de novo teste; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e lavrar a ata do teste com datas de início e término, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-02' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando etapas subsequentes (contrapiso, assentamento, tráfego de obra) forem liberadas sobre a impermeabilização sem a proteção mecânica executada.',
  texto_fundamentacao_normativa = 'A proteção mecânica deve ser executada antes da liberação para as etapas seguintes, resguardando o sistema de impermeabilização contra perfurações, abrasão e danos por tráfego e por serviços subsequentes. Fundamenta-se pela NBR 9574 (execução de impermeabilização), pelas recomendações do fabricante e pelo projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério de execução da proteção antes da liberação integra o plano de inspeção como requisito de aceitação e de sequenciamento das atividades.',
  texto_risco_consequencia = 'A liberação de etapas subsequentes sem proteção mecânica expõe a manta/membrana a perfurações e abrasão por tráfego, ferramentas e materiais, comprometendo a estanqueidade já ensaiada e gerando falhas ocultas sob o recobrimento, de correção onerosa. A permanência da condição mantém o sistema vulnerável a danos até a execução da proteção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) interromper a liberação de serviços sobre a área e verificar a integridade do sistema já aplicado; (ii) executar a proteção mecânica especificada (camada separadora e argamassa/proteção conforme projeto e fabricante) antes de autorizar as etapas seguintes; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) da proteção concluída por área, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-02' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a ausência de registro fotográfico impedir a rastreabilidade e a aceitação da área, ou quando o recobrimento tiver ocorrido sem qualquer evidência arquivada.',
  texto_fundamentacao_normativa = 'O registro fotográfico da impermeabilização concluída, antes do recobrimento e arquivado por área, é o elemento de rastreabilidade que documenta a execução dos detalhes e permite a verificação futura sem intervenção destrutiva. Fundamenta-se pelo plano de inspeção e pelo sistema de gestão da qualidade da obra e pelo projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que estabelecem a evidência documental como requisito de aceitação. O critério de evidência arquivada por área impermeabilizada constitui requisito verificável de encerramento da etapa.',
  texto_risco_consequencia = 'A ausência de registro fotográfico antes do recobrimento impede a comprovação da correta execução e a rastreabilidade por área, dificultando a apuração de causas em caso de infiltração futura e podendo exigir aberturas exploratórias para diagnóstico, com custo e transtorno. A permanência da condição mantém a etapa sem evidência documental até a regularização. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) levantar quais áreas ficaram sem registro antes do recobrimento e verificar se ainda há acesso; (ii) regularizar o acervo fotográfico das áreas ainda expostas e formalizar procedimento para registro obrigatório antes de qualquer recobrimento nas próximas frentes; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) organizado e identificado por área, arquivado no dossiê da qualidade, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-02' and item_numero = 7;

-- ED-03 (8 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o diâmetro ou o material instalado divergir do dimensionamento e comprometer a vazão de projeto, a compatibilidade com a pressão de serviço ou a resistência do trecho.',
  texto_fundamentacao_normativa = 'O traçado das prumadas e ramais, bem como os diâmetros e materiais empregados, devem reproduzir fielmente o dimensionamento hidráulico do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que estabelece a rede de distribuição e sua compatibilização com forros, shafts e furações estruturais. Aplica-se a NBR 5626 (sistemas prediais de água fria e água quente), que orienta o dimensionamento, a seleção de materiais e a execução das tubulações prediais. O critério "Traçado, diâmetros e materiais conferidos" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa, conferido contra os isométricos e as especificações técnicas.',
  texto_risco_consequencia = 'A instalação de prumadas ou ramais fora do traçado, com diâmetro reduzido ou material distinto do especificado, provoca perda de carga excessiva, vazão insuficiente nos pontos de utilização, ruídos e maior suscetibilidade a golpe de aríete, além de eventual incompatibilidade química ou de pressão que reduz a vida útil da rede. A permanência da condição mantém a rede em desconformidade com o projeto até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) conferir o trecho contra o isométrico e a lista de materiais do projeto executivo aprovado, identificando os pontos de divergência de traçado, diâmetro ou material; (ii) readequar ou substituir os segmentos não conformes, restabelecendo o traçado, os diâmetros e os materiais especificados; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e atualização do as-built, submetendo o trecho à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-03' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a declividade insuficiente ou invertida ocorrer em coletores ou sub-coletores que escoem por gravidade, sob risco de refluxo e obstrução recorrente.',
  texto_fundamentacao_normativa = 'Os ramais e coletores de esgoto sanitário devem ser assentados com a declividade mínima associada ao seu diâmetro, de modo a garantir o escoamento por gravidade com velocidade de autolimpeza. Aplica-se a NBR 8160 (sistemas prediais de esgoto sanitário — projeto e execução), que fixa as declividades mínimas por diâmetro, em conjunto com o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Declividades mínimas por diâmetro atendidas" integra o plano de inspeção da obra e constitui requisito verificável de aceitação, conferido por nível/mangueira de nível ou topografia antes do fechamento.',
  texto_risco_consequencia = 'Caimentos abaixo do mínimo, nulos ou invertidos comprometem a autolimpeza da tubulação, favorecendo a deposição de sólidos, obstruções recorrentes, retorno de esgoto e exalação de odores nas áreas servidas. A permanência da condição mantém ativo o risco sanitário e de transbordamento até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) levantar as cotas de fundo do trecho e confrontar a declividade executada com a mínima exigida para o diâmetro conforme projeto; (ii) refazer o assentamento e a fixação da tubulação, reconstituindo o caimento contínuo e sem contraflechas até o ponto de conexão; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e nova conferência de nível antes do fechamento, submetendo à reinspeção para encerramento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-03' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando o espaçamento excessivo ou a ausência de suportes gerar flechas, tensões nas juntas ou desalinhamento capaz de comprometer a estanqueidade ou o caimento da tubulação.',
  texto_fundamentacao_normativa = 'Os suportes e fixações devem sustentar a tubulação sem impor esforços indevidos às juntas, com espaçamento compatível com o material, o diâmetro e a dilatação previstos, conforme as recomendações do fabricante do sistema e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Na ausência de valor normativo específico assumido com certeza, o espaçamento e o tipo de suporte adotam a especificação técnica do fabricante e as boas práticas de execução de instalações prediais, que também asseguram a acomodação das variações térmicas na água quente. O critério "Espaçamento conforme material da tubulação" integra o plano de inspeção e constitui requisito verificável de aceitação.',
  texto_risco_consequencia = 'Suportes insuficientes, mal espaçados ou inadequados ao material permitem flechas, vibração e concentração de tensões nas conexões, com risco de vazamentos, ruídos, perda de caimento no esgoto e ruptura de juntas ao longo do tempo, sobretudo em trechos de água quente sujeitos à dilatação. A permanência da condição mantém a tubulação mecanicamente vulnerável até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) verificar o espaçamento, o tipo e a fixação dos suportes contra a especificação do fabricante e o projeto, identificando trechos sem apoio adequado; (ii) instalar ou reposicionar os suportes e abraçadeiras, prevendo folga para dilatação onde aplicável e eliminando flechas e desalinhamentos; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}), submetendo o trecho à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-03' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — a etapa não pode ser liberada nem os trechos fechados sem o ensaio aprovado; rebaixar a Maior somente se, comprovada a estanqueidade por reensaio, restar apenas pendência documental do relatório.',
  texto_fundamentacao_normativa = 'O ensaio de pressão (estanqueidade) das redes de água fria e quente é condição de aceitação da instalação, executado com a pressão e o tempo de manutenção da carga estabelecidos e formalizado em relatório assinado. Aplica-se a NBR 5626 (sistemas prediais de água fria e água quente), expressamente referida no critério, em conjunto com o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Pressão e tempo conforme NBR 5626; relatório assinado" integra o plano de inspeção e constitui requisito verificável e documental de liberação da etapa, prévio ao fechamento de shafts e revestimentos.',
  texto_risco_consequencia = 'A ausência do ensaio, sua execução fora da pressão/tempo exigidos ou a falta do relatório assinado libera para fechamento uma rede cuja estanqueidade não foi comprovada, admitindo vazamentos ocultos que se manifestam após o revestimento, com infiltração, dano a acabamentos e demolição para reparo. A permanência da condição mantém a rede sem comprovação de estanqueidade até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) executar (ou repetir) o ensaio de pressão da água fria e quente na pressão e no tempo de manutenção da carga exigidos, com manômetro aferido e a rede pressurizada; (ii) sanar eventuais quedas de pressão localizando e corrigindo as juntas ou pontos com vazamento e reensaiando o trecho até a aprovação; (iii) emitir e anexar o relatório de ensaio assinado e evidenciar com registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-03' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — os trechos não podem ser fechados sem o ensaio de estanqueidade aprovado; rebaixar a Maior apenas quando, confirmada a estanqueidade em reensaio, restar somente pendência de registro/documentação.',
  texto_fundamentacao_normativa = 'A rede de esgoto e ventilação deve ter sua estanqueidade comprovada antes do fechamento, por ensaio de água ou de fumaça que evidencie a ausência de vazamentos nas juntas e conexões. Aplica-se a NBR 8160 (sistemas prediais de esgoto sanitário — projeto e execução), que prevê a verificação de estanqueidade da tubulação, em conjunto com o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Teste de água/fumaça antes do fechamento" integra o plano de inspeção e constitui requisito verificável de aceitação, obrigatoriamente anterior ao embutimento e ao revestimento.',
  texto_risco_consequencia = 'Fechar a rede de esgoto sem comprovar a estanqueidade admite vazamentos ocultos e escape de gases nas juntas, com contaminação de forros e alvenarias, odores nas áreas servidas e necessidade de demolição para reparo após o acabamento. A permanência da condição mantém ativo o risco sanitário e de infiltração até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) executar o ensaio de estanqueidade por água ou fumaça em toda a rede, com os pontos vedados e a coluna/pressão de ensaio adequadas, antes de qualquer fechamento; (ii) corrigir as juntas ou conexões que apresentarem vazamento ou passagem de fumaça e repetir o ensaio até a aprovação do trecho; (iii) registrar o resultado e evidenciar com registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-03' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a ausência ou descontinuidade do isolamento comprometer o desempenho térmico exigido em projeto, gerar condensação sobre outros sistemas ou contrariar requisito contratual de eficiência.',
  texto_fundamentacao_normativa = 'As tubulações de água quente devem receber o isolamento térmico definido em projeto (tipo, espessura e continuidade), de modo a limitar as perdas de calor e assegurar a temperatura de utilização com eficiência energética. A exigência decorre do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}} e de suas especificações técnicas, apoiadas nas boas práticas de sistemas prediais de água quente; não se cita número normativo específico de isolamento por não se ter certeza de sua aplicação a este item. O critério "Conforme projeto" integra o plano de inspeção e constitui requisito verificável de aceitação, conferido quanto à cobertura integral, à espessura e à proteção do isolante.',
  texto_risco_consequencia = 'A falta, a insuficiência ou a descontinuidade do isolamento térmico na água quente provoca perda de calor, queda da temperatura nos pontos de consumo, maior consumo de energia para reaquecimento e possível condensação sobre a própria tubulação e sistemas vizinhos. A permanência da condição mantém o desempenho térmico da rede aquém do projeto até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) mapear os trechos de água quente sem isolamento ou com isolante de espessura/tipo divergentes do projeto, incluindo conexões e registros; (ii) aplicar ou complementar o isolamento térmico especificado, garantindo continuidade nas juntas, curvas e acessórios e a devida proteção mecânica; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}), submetendo o trecho à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-03' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Observação — elevar a Menor ou Maior quando a ausência de identificação em shafts e áreas técnicas dificultar a operação segura, a manutenção emergencial ou o bloqueio correto de redes distintas.',
  texto_fundamentacao_normativa = 'As tubulações em shafts e áreas técnicas devem ser identificadas por cores e/ou etiquetas que distingam os fluidos e sistemas (água fria, água quente, esgoto, ventilação, incêndio), facilitando a operação e a manutenção seguras. A exigência apoia-se no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, no padrão de identificação adotado pela obra e nas boas práticas de sinalização de instalações; adota-se o critério do item sem atribuir número normativo cuja aplicação não se confirme com certeza. O critério "Cores/etiquetas em shafts e áreas técnicas" integra o plano de inspeção e constitui requisito verificável de aceitação.',
  texto_risco_consequencia = 'A ausência ou a incorreção da identificação das tubulações dificulta a operação e a manutenção, aumentando o tempo de resposta em emergências e o risco de manobra ou corte na rede errada, com possibilidade de interrupção indevida de serviço ou intervenção sobre sistema pressurizado. A permanência da condição mantém as redes sem distinção visual clara até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) confrontar a identificação existente com o padrão de cores/etiquetas adotado pela obra, listando as tubulações não identificadas ou com marcação ambígua em shafts e áreas técnicas; (ii) aplicar as cores e etiquetas correspondentes a cada fluido/sistema, com legibilidade e indicação de sentido de fluxo onde aplicável; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-03' and item_numero = 7;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a interligação divergente à rede pública ou ao sistema de tratamento local caracterizar lançamento irregular, refluxo ou não atendimento a condicionante da concessionária/órgão ambiental.',
  texto_fundamentacao_normativa = 'As interligações finais das redes prediais à infraestrutura externa — rede da concessionária ou sistema local (fossa/tratamento) — devem seguir o ponto, o tipo e as condições definidos no projeto aprovado e nas normas da concessionária local. Aplica-se a NBR 8160 (sistemas prediais de esgoto sanitário — projeto e execução) na interface predial de esgoto, complementada pelas exigências da concessionária e pelo projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}; para sistema local de tratamento, observam-se as condições de projeto do tanque séptico/infiltração aprovadas. O critério "Concessionária/fossa conforme projeto aprovado" integra o plano de inspeção e constitui requisito verificável de aceitação da interligação.',
  texto_risco_consequencia = 'A interligação executada em ponto, cota ou configuração distintos do projeto e das normas da concessionária pode caracterizar lançamento irregular, provocar refluxo entre redes, contaminação do solo ou de águas pluviais e ensejar autuação e embargo, além de impedir a ligação definitiva e o habite-se. A permanência da condição mantém a edificação sem interligação regular às redes externas até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) conferir o ponto, a cota e o tipo de interligação executados contra o projeto aprovado e as exigências da concessionária ou do sistema local de tratamento; (ii) readequar a conexão à rede pública ou à fossa/sistema de tratamento, incluindo caixas, dispositivos de inspeção e vedações, restabelecendo a conformidade com o projeto; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e a documentação de aprovação da concessionária/órgão quando aplicável, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-03' and item_numero = 8;

-- ED-04 (7 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a taxa de ocupação exceder o limite normativo ou o desalinhamento/desnível de caixas inviabilizar a enfiação ou o acabamento dos espelhos.',
  texto_fundamentacao_normativa = 'O encaminhamento de eletrodutos e o posicionamento das caixas devem reproduzir o projeto elétrico executivo, respeitando a taxa máxima de ocupação dos condutos, o alinhamento das linhas e o nivelamento das caixas, de modo a permitir a passagem, a troca e a dissipação térmica dos condutores. Aplicam-se a NBR 5410 (instalações elétricas de baixa tensão), quanto às regras de ocupação e de encaminhamento de linhas elétricas, e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que define traçados, bitolas e locação das caixas. O critério "Ocupação máxima, alinhamento e nivelamento de caixas" integra o plano de inspeção e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Eletrodutos com ocupação acima do limite ou caixas desalinhadas e desniveladas dificultam a enfiação, danificam a isolação dos condutores durante a passagem, prejudicam a dissipação de calor e comprometem o assentamento de espelhos e acabamentos, podendo exigir reabertura de rasgos e retrabalho de alvenaria. A permanência da condição mantém ativo o desvio construtivo e agrava o risco de dano aos cabos até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) conferir a taxa de ocupação de cada trecho de eletroduto frente às bitolas de projeto, redistribuindo circuitos ou ampliando o conduto quando excedido o limite; (ii) reposicionar, alinhar e nivelar as caixas conforme locação de projeto, garantindo prumo, esquadro e cota de acabamento; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-04' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando houver dano à isolação, emenda indevida em conduto ou ausência de identificação que impeça a operação segura do circuito.',
  texto_fundamentacao_normativa = 'A enfiação dos condutores deve ser executada somente após a conclusão das fases úmidas (contrapisos, rebocos, argamassas), com os condutos secos e desobstruídos, preservando a integridade da isolação, mantendo folga adequada nas caixas e identificando cada condutor por circuito e função. Aplica-se a NBR 5410 (instalações elétricas de baixa tensão), quanto à execução de linhas elétricas, seções mínimas, identificação de condutores e proteção contra danos mecânicos e umidade, complementada pelo projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Condutores íntegros, com folga e identificação" integra o plano de inspeção e constitui requisito verificável de aceitação.',
  texto_risco_consequencia = 'Enfiação realizada antes das fases úmidas ou sem folga e identificação expõe os condutores à umidade e a danos mecânicos, dificulta futuras manutenções e ligações, e pode ocasionar falhas de isolação, curtos-circuitos e riscos de choque e incêndio. A permanência da condição mantém latente o risco elétrico e a dificuldade operacional dos circuitos até a correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) inspecionar a isolação dos condutores já instalados, substituindo os que apresentem danos, ressecamento ou contaminação por umidade; (ii) assegurar folga mínima nas caixas e identificar cada condutor por circuito e função conforme projeto, executando a enfiação apenas com condutos secos; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-04' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — dispositivos de proteção (DR/DPS) são requisito de segurança de pessoas e da instalação; manter como Maior apenas quando a única pendência for a identificação de circuitos, sem ausência ou subdimensionamento de dispositivos.',
  texto_fundamentacao_normativa = 'Os quadros de distribuição devem conter dispositivo diferencial-residual (DR) para proteção contra contatos indiretos e correntes de fuga, dispositivo de proteção contra surtos (DPS) conforme a análise de risco, disjuntores dimensionados por circuito e identificação clara e permanente de todos os circuitos. Aplica-se a NBR 5410 (instalações elétricas de baixa tensão), que estabelece a proteção diferencial-residual, a proteção contra sobrecorrentes e sobretensões e a identificação dos circuitos nos quadros, em conjunto com a NR-10 quanto à segurança em instalações elétricas e com o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Circuitos identificados; dispositivos conforme projeto" integra o plano de inspeção e constitui requisito verificável de aceitação.',
  texto_risco_consequencia = 'Quadros sem DR, sem DPS ou com dispositivos em desacordo com o projeto suprimem proteções essenciais contra choque elétrico, correntes de fuga e surtos, expondo usuários a acidentes graves e a instalação a danos por sobretensão; a falta de identificação dificulta manobras e manutenções seguras. A permanência da condição mantém ativo o risco à segurança das pessoas e do patrimônio até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) instalar e/ou substituir os dispositivos DR, DPS e disjuntores conforme o projeto e o esquema unifilar aprovado, verificando o dimensionamento por circuito; (ii) identificar de forma clara e permanente todos os circuitos no quadro, atualizando o diagrama afixado na porta; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e ensaio funcional do DR (botão de teste), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-04' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — a continuidade do condutor de proteção e as equipotencializações são a barreira primária contra choque elétrico; qualquer descontinuidade caracteriza risco grave e imediato.',
  texto_fundamentacao_normativa = 'O esquema de aterramento deve assegurar continuidade elétrica do condutor de proteção (PE) do quadro até cada ponto de utilização, com as equipotencializações principal e suplementares executadas, interligando massas e elementos condutivos estranhos à instalação. Aplica-se a NBR 5410 (instalações elétricas de baixa tensão), que define os esquemas de aterramento, o condutor de proteção e a equipotencialização como medidas de proteção contra choques elétricos, em conjunto com a NR-10 e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Condutor PE contínuo; equipotencializações executadas" integra o plano de inspeção e constitui requisito verificável de aceitação.',
  texto_risco_consequencia = 'Condutor de proteção interrompido ou equipotencializações não executadas impedem o escoamento de correntes de falta e a atuação das proteções, mantendo massas sob potencial perigoso e expondo os usuários a choque elétrico de consequências potencialmente fatais. A permanência da condição mantém ativo o risco de acidente elétrico até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) verificar a continuidade do condutor PE em todos os circuitos e pontos, por medição de continuidade/resistência, restabelecendo conexões interrompidas ou frouxas; (ii) executar e/ou completar a equipotencialização principal e as suplementares, interligando massas e elementos condutivos conforme projeto; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e laudo de medição, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-04' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a divergência de quantidade ou posição de pontos comprometer o uso previsto do ambiente, a acessibilidade ou o atendimento a cargas essenciais.',
  texto_fundamentacao_normativa = 'A quantidade, a tipologia e o posicionamento de tomadas, interruptores e luminárias devem reproduzir o projeto elétrico e o projeto de arquitetura/luminotécnico, respeitando cotas de altura, alinhamentos e a distribuição prevista por ambiente. Aplica-se a NBR 5410 (instalações elétricas de baixa tensão), quanto à previsão mínima de pontos e à distribuição de circuitos terminais, em conjunto com o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que fixa a locação dos pontos. O critério "Tomadas, interruptores e luminárias em quantidade/posição" integra o plano de inspeção e constitui requisito verificável de aceitação.',
  texto_risco_consequencia = 'Pontos executados em quantidade ou posição divergente do projeto comprometem o uso funcional dos ambientes, induzem ao uso de extensões e adaptações improvisadas, prejudicam a distribuição de cargas prevista e podem exigir reabertura de acabamentos para correção. A permanência da condição mantém a inadequação funcional e o desvio de projeto até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) confrontar a quantidade, a tipologia e a locação dos pontos executados com o projeto elétrico e arquitetônico, mapeando as divergências; (ii) executar, remanejar ou complementar os pontos de tomada, interruptores e luminárias conforme projeto, respeitando cotas e alinhamentos; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-04' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a energização houver ocorrido sem o ensaio ou quando os valores medidos de isolamento estiverem abaixo do mínimo admissível.',
  texto_fundamentacao_normativa = 'A medição da resistência de isolamento (megôhmetro/megger) deve ser realizada por circuito antes da energização, comprovando a integridade da isolação dos condutores e a ausência de falhas entre condutores e entre condutor e terra. Aplica-se a NBR 5410 (instalações elétricas de baixa tensão), que prevê a verificação final da instalação, incluindo o ensaio de resistência de isolamento e os valores mínimos admissíveis, em conjunto com a NR-10 quanto aos procedimentos prévios à energização e ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Megger por circuito antes da energização" integra o plano de inspeção e constitui requisito verificável de aceitação.',
  texto_risco_consequencia = 'A energização sem medição de isolamento, ou com valores abaixo do mínimo, permite colocar em serviço circuitos com isolação comprometida, gerando fugas de corrente, curtos-circuitos, risco de choque elétrico e princípio de incêndio, além de dano a equipamentos ligados à instalação. A permanência da condição mantém oculta a eventual falha de isolação até a sua manifestação em operação. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) executar a medição de resistência de isolamento com megôhmetro, circuito a circuito, com a instalação desenergizada e registrando os valores obtidos; (ii) investigar e sanar os circuitos que apresentarem valores abaixo do mínimo admissível antes de liberar a energização; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e relatório de ensaio assinado pelo responsável técnico, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-04' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — o SPDA protege a edificação e seus ocupantes contra descargas atmosféricas; captação, descidas ou aterramento incompletos configuram risco grave e comprometem a proteção do sistema.',
  texto_fundamentacao_normativa = 'O Sistema de Proteção contra Descargas Atmosféricas (SPDA) predial deve ser executado com subsistema de captação, condutores de descida e sistema de aterramento contínuos e interligados, conforme o método de proteção e o nível definidos em projeto. Aplica-se a NBR 5419 (proteção contra descargas atmosféricas), expressamente adotada no critério deste item, que define a captação, as descidas, o aterramento e a equipotencialização do SPDA, em conjunto com o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Captação, descidas e aterramento conforme NBR 5419" integra o plano de inspeção e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'SPDA com captação, descidas ou aterramento incompletos ou descontínuos deixa a edificação sem caminho seguro para a corrente de descarga atmosférica, elevando o risco de danos estruturais, incêndio, avaria de sistemas elétricos e eletrônicos e risco de vida aos ocupantes por tensões de passo e de toque. A permanência da condição mantém a edificação desprotegida contra descargas atmosféricas até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) verificar a integridade e a continuidade dos subsistemas de captação, descidas e aterramento, restabelecendo conexões, soldas e emendas conforme projeto e NBR 5419; (ii) medir a resistência de aterramento e a continuidade das descidas, corrigindo os pontos fora dos parâmetros de projeto; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e laudo/medição do SPDA assinado pelo responsável técnico, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-04' and item_numero = 7;

-- ED-05 (8 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a espessura excessiva, o traço inadequado ou a cura deficiente comprometerem a aderência do revestimento ao substrato e o desempenho das camadas de acabamento subsequentes',
  texto_fundamentacao_normativa = 'O chapisco e o emboço constituem as camadas de preparo e regularização que asseguram a ancoragem e a coesão do sistema de revestimento; por isso traço, cura e espessura devem observar a especificação. Aplicam-se a NBR 7200 (execução de revestimento de paredes e tetos de argamassas inorgânicas) e a NBR 13749 (especificação de revestimentos de argamassas inorgânicas), que disciplinam a execução das camadas e os limites de espessura, além do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, e da especificação da argamassa. O critério "Traço, cura e espessuras dentro dos limites" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Chapisco ou emboço executados fora do traço, com cura deficiente ou espessura em desacordo comprometem a aderência e a coesão do sistema, favorecendo fissuração, empolamento e descolamento das camadas superiores, com necessidade de remoção e refazimento do pano e o consequente sobrecusto e atraso. A permanência da condição mantém latente a perda de aderência até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) verificar o traço, o procedimento de cura e a espessura executada do trecho, confrontando-os com a especificação e o projeto executivo aprovado; (ii) remover e reexecutar as camadas fora dos limites, adotando cura úmida e espessura compatível com o suporte; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e, quando cabível, ensaio de aderência, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-05' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o desvio de planeza comprometer o assentamento das placas cerâmicas, gerar juntas irregulares ou provocar acúmulo de água em superfícies horizontais',
  texto_fundamentacao_normativa = 'A planeza da superfície é condição para o assentamento uniforme do revestimento e para o desempenho estético e funcional do pano, sendo aferida com régua de 2 m aplicada em diversas posições. Aplica-se a NBR 13749 (especificação de revestimentos de argamassas inorgânicas), que estabelece as tolerâncias de planeza verificáveis com régua de 2 m, além do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Régua de 2 m dentro da tolerância da norma" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Superfície com desvio de planeza acima da tolerância dificulta o assentamento regular das placas, produz variação de espessura da argamassa colante, juntas desalinhadas e ressaltos entre peças, além de comprometer o caimento em superfícies horizontais e a aparência final, exigindo retrabalho de regularização. A permanência da condição mantém o desvio geométrico ativo até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) remapear o pano com régua de 2 m, identificando e demarcando os pontos fora da tolerância; (ii) corrigir a planeza mediante regularização localizada da camada, respeitando as espessuras admissíveis, ou refazer o trecho quando necessário; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e nova verificação com régua de 2 m, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-05' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica em fachadas e no assentamento de peças de grande formato, em que a perda do tempo em aberto ou a ausência de dupla colagem pode resultar em descolamento e queda de placas',
  texto_fundamentacao_normativa = 'A eficácia da colagem depende de a placa ser assentada dentro do tempo em aberto da argamassa colante, antes da formação de película superficial, adotando-se dupla colagem em peças de grande formato para garantir o preenchimento sob a placa. Aplicam-se a NBR 14081 (argamassa colante industrializada para assentamento de placas cerâmicas), que define os requisitos e o tempo em aberto do produto, e as recomendações do fabricante, além do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Pot life respeitado; dupla colagem em peças grandes" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'O assentamento após o tempo em aberto ou sem dupla colagem em peças grandes reduz a área de contato efetiva e a resistência de aderência, gerando vazios sob a placa e risco de destacamento; em fachadas, a eventual queda de placas configura risco à segurança de terceiros, além de impor a remoção e o reassentamento do pano. A permanência da condição mantém o déficit de aderência ativo até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) suspender o assentamento e revisar o procedimento, respeitando o tempo em aberto e refazendo o cordão sempre que houver formação de película; (ii) adotar dupla colagem nas peças de grande formato e reassentar as placas com aderência deficiente, verificando o preenchimento sob a placa; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e verificação por percussão, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-05' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica em fachadas e em grandes panos contínuos, onde a ausência ou o posicionamento incorreto das juntas de movimentação favorece tensões acumuladas e descolamento generalizado',
  texto_fundamentacao_normativa = 'As juntas de assentamento e de movimentação absorvem as deformações térmicas e higroscópicas do revestimento e do substrato, evitando o acúmulo de tensões, e devem obedecer ao espaçamento e às posições definidos em projeto. Aplicam-se a NBR 13753 (revestimento de piso interno ou externo com placas cerâmicas e argamassa colante) e a NBR 13755 (revestimento de paredes externas e fachadas com placas cerâmicas e argamassa colante), que disciplinam as juntas de assentamento, de movimentação e de dessolidarização, além do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Espaçamento e posições conforme projeto/norma" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Juntas ausentes, subdimensionadas ou fora de posição impedem a acomodação das deformações do conjunto, gerando concentração de tensões, fissuras, gretamento do rejunte e descolamento de placas, sobretudo em fachadas e grandes panos, com necessidade de refazimento e risco à segurança. A permanência da condição mantém o sistema tensionado até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) conferir o traçado, o espaçamento e o posicionamento das juntas executadas frente ao projeto e à norma aplicável; (ii) executar ou reposicionar as juntas de assentamento e de movimentação faltantes, com material de preenchimento adequado à sua função; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e mapeamento das juntas, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-05' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter como Crítica em fachadas e áreas críticas quando o ensaio exigido não for realizado ou resultar abaixo do mínimo; reduzir a Maior apenas em situações de baixo risco de queda devidamente justificadas',
  texto_fundamentacao_normativa = 'O ensaio de resistência de aderência à tração comprova, por amostragem, que o revestimento atende ao valor mínimo de aderência requerido, sendo obrigatório quando exigido em projeto para fachadas e áreas críticas. Aplicam-se a NBR 13528 (determinação da resistência de aderência à tração de revestimentos de argamassa) e a NBR 13755 (revestimento de paredes externas e fachadas com placas cerâmicas), que fundamentam o ensaio e a aceitação em fachadas, além do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "NBR 13528 em fachadas/áreas críticas" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'A ausência do ensaio de arrancamento onde exigido, ou resultados abaixo do mínimo, impede a comprovação da aderência do revestimento e mantém indeterminada a segurança do pano; em fachadas, essa incerteza está diretamente associada ao risco de destacamento e queda de placas sobre pessoas e bens, além de inviabilizar o recebimento formal da etapa. A permanência da condição mantém o pano sem comprovação de desempenho até a efetiva verificação. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) programar e executar o ensaio de resistência de aderência à tração por laboratório qualificado, nos pontos e na quantidade de amostras exigidos; (ii) tratar as regiões reprovadas com remoção e reexecução do revestimento, seguidas de novo ensaio de comprovação; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e os laudos de ensaio, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-05' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o caimento incorreto comprometer o escoamento em áreas molhadas com impermeabilização, favorecendo empoçamento e infiltração para ambientes ou pavimentos inferiores',
  texto_fundamentacao_normativa = 'O caimento das áreas molhadas deve conduzir a água aos ralos de forma contínua, sendo conferido antes do assentamento por constituir condição de difícil correção após a execução do revestimento. A fundamentação decorre do projeto hidrossanitário e de impermeabilização aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que define as declividades e a locação dos ralos, e das boas práticas de execução, que recomendam a conferência do caimento com nível antes do assentamento das placas. O critério "Direção aos ralos conferida antes do assentamento" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Caimento insuficiente ou em direção incorreta provoca empoçamento de água sobre o piso, sobrecarga do sistema de impermeabilização e infiltrações para paredes, ambientes contíguos ou pavimentos inferiores, com danos a acabamentos e necessidade de remoção do revestimento para recuperação do caimento. A permanência da condição mantém o escoamento deficiente ativo até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) conferir a declividade e o sentido de escoamento com nível, do ponto mais alto até os ralos, confrontando-os com o projeto; (ii) corrigir o caimento mediante regularização do contrapiso e restabelecimento da direção aos ralos antes do assentamento definitivo; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e teste de escoamento de água (teste de lâmina), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-05' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior em áreas molhadas e fachadas, onde o rejunte atua como barreira à infiltração e sua deficiência compromete a estanqueidade do sistema',
  texto_fundamentacao_normativa = 'O rejuntamento sela as juntas entre placas, contribuindo para a estanqueidade e a durabilidade do revestimento, e deve empregar material compatível e ser executado no prazo de espera indicado pelo fabricante, após a cura da argamassa colante. Aplicam-se a NBR 14992 (argamassa à base de cimento Portland para rejuntamento de placas cerâmicas), quanto ao material, e as recomendações do fabricante quanto ao prazo, além do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, e das NBR 13753/13755 quanto à execução. O critério "Material e prazo conforme fabricante" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Rejunte executado com material inadequado ou fora do prazo recomendado apresenta baixa coesão, fissuração, retração e destacamento nas juntas, permitindo a percolação de água para o substrato e comprometendo a estanqueidade e a estética do revestimento, com necessidade de remoção e refazimento do rejuntamento. A permanência da condição mantém as juntas vulneráveis à infiltração até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) verificar o material de rejuntamento especificado e o cumprimento do prazo de espera indicado pelo fabricante; (ii) remover o rejunte deficiente e reexecutar as juntas com o produto adequado, garantindo preenchimento e acabamento uniformes; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e, em áreas molhadas, teste de estanqueidade, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-05' and item_numero = 7;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica em fachadas e áreas elevadas, em que a incidência de peças ocas acima do limite indica risco iminente de destacamento e queda de placas sobre pessoas',
  texto_fundamentacao_normativa = 'A verificação por percussão, executada por amostragem, identifica vazios e falhas de aderência sob as placas pelo som cavo, sendo indicador direto da qualidade do assentamento e da segurança do revestimento. A fundamentação decorre das NBR 13753 e NBR 13755 (revestimentos com placas cerâmicas e argamassa colante em pisos e fachadas), quanto à inspeção e aceitação, e das boas práticas de recebimento, que estabelecem a verificação de som cavo, além do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Sem peças ocas acima do limite" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'A presença de peças ocas acima do limite admitido revela vazios e aderência insuficiente sob as placas, condição que evolui para destacamento e, em fachadas ou áreas elevadas, para a queda de placas com risco à segurança de terceiros, exigindo a remoção e o reassentamento das peças comprometidas. A permanência da condição mantém o revestimento com aderência deficiente até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) ampliar a verificação por percussão para mapear a extensão das peças ocas no pano; (ii) remover e reassentar as placas identificadas como ocas, com argamassa colante adequada e preenchimento pleno sob a placa; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e nova verificação por percussão, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-05' and item_numero = 8;

-- ED-06 (7 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a divergência de vão obrigar a folgas fora da faixa do fabricante, comprometendo assentamento, vedação ou operação da esquadria',
  texto_fundamentacao_normativa = 'A compatibilização entre a medida do vão e a esquadria deve respeitar as folgas de instalação prescritas pelo fabricante, condição que garante o encaixe do contramarco, a acomodação de dilatações e a continuidade posterior da vedação. Aplicam-se a NBR 10821 (esquadrias externas para edificações), as especificações técnicas do fabricante e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que definem dimensões nominais e tolerâncias de vão. O critério "Folgas de instalação conforme fabricante" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Vão fora de medida ou folga incompatível com a recomendação do fabricante impede a fixação correta da esquadria, força improvisos de calço e sobrecarrega o selante, gerando infiltração, empenamento do quadro e mau funcionamento das folhas ao longo da vida útil. A permanência da condição mantém a esquadria sob esforço indevido e antecipa a degradação da vedação. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) remedir o vão (largura, altura e diagonais) e confrontar com a esquadria e com a faixa de folga do fabricante; (ii) adequar o vão por recorte, recomposição de contramarco ou substituição da esquadria, conforme o caso, restabelecendo as folgas especificadas; (iii) evidenciar a correção com registro fotográfico e ficha de medição ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-06' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a fixação insuficiente comprometer a estabilidade da esquadria ou a segurança de terceiros sob a fachada',
  texto_fundamentacao_normativa = 'A fixação e o chumbamento por contramarco devem seguir o tipo, a quantidade, o espaçamento e o padrão de ancoragem definidos em projeto, assegurando a transferência de esforços de vento e uso ao substrato. Aplicam-se a NBR 10821 (esquadrias externas para edificações), as instruções do fabricante do sistema e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que fixam o detalhe de contramarco e fixações. O critério "Contramarco e fixações no padrão do projeto" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Fixação fora do padrão de projeto — pontos de ancoragem faltantes, mal distribuídos ou subdimensionados — reduz a resistência da esquadria às cargas de vento e ao uso, podendo provocar frestas, deslocamento do quadro e, no limite, desprendimento com risco à segurança de pessoas sob a fachada. A permanência da condição mantém a esquadria com ancoragem deficiente até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) mapear os pontos de fixação executados e confrontá-los com o detalhe de contramarco e ancoragem do projeto e do fabricante; (ii) complementar ou refazer o chumbamento e as fixações, garantindo tipo, quantidade e espaçamento especificados e o preenchimento adequado entre contramarco e alvenaria; (iii) evidenciar a correção com registro fotográfico dos pontos de ancoragem ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-06' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o desaprumo ou desnível já estiver fixado definitivamente e comprometer a operação das folhas ou a vedação da esquadria',
  texto_fundamentacao_normativa = 'O nivelamento, o prumo e o esquadro da esquadria devem ser conferidos e travados antes da fixação definitiva, pois é nesse momento que se garante a geometria correta do quadro e o assentamento uniforme das folhas. A verificação apoia-se nas boas práticas de instalação de esquadrias, nas instruções do fabricante e no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que definem os planos de referência e alinhamentos. O critério "Conferidos antes da fixação definitiva" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Esquadria fixada fora de prumo, nível ou esquadro produz folgas desiguais entre folha e quadro, atrito e desregulagem de ferragens, além de comprometer a vedação e o aspecto final; corrigir após o chumbamento definitivo exige retrabalho de demolição e reinstalação. A permanência da condição mantém o desvio geométrico incorporado à esquadria até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reconferir nível, prumo e esquadro do quadro com nível e esquadro de precisão, antes de qualquer travamento definitivo; (ii) reposicionar e recalçar a esquadria até o atendimento aos planos de referência do projeto, travando-a apenas após a conferência; (iii) evidenciar a correção com registro fotográfico e leituras de prumo/nível ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-06' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a falha de vedação ocorrer em esquadria de fachada exposta à água ou em ambiente que exija estanqueidade',
  texto_fundamentacao_normativa = 'A vedação perimetral com selante e/ou espuma expansiva deve ser contínua e sem falhas, constituindo a barreira que impede a passagem de água e ar entre esquadria e substrato. Aplicam-se as instruções do fabricante do selante e da espuma (preparo do substrato, largura/profundidade do cordão e cura), as boas práticas de estanqueidade e o desempenho de vedação previsto no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Selante/espuma contínuos, sem falhas" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Vedação descontínua, com bolhas, falhas ou cordão mal aderido, cria caminhos preferenciais de infiltração de água e passagem de ar, resultando em manchas, deterioração de acabamentos, corrosão de fixações e perda de conforto térmico e acústico. A permanência da condição mantém a interface esquadria-substrato permeável até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) inspecionar todo o perímetro, identificando trechos com falha, descolamento ou descontinuidade do selante/espuma; (ii) remover o material comprometido, preparar o substrato e reaplicar selante/espuma de forma contínua, respeitando a geometria do cordão e o tempo de cura do fabricante; (iii) evidenciar a correção com registro fotográfico do perímetro vedado ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-06' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando o defeito de operação impedir o uso, o fechamento seguro ou o travamento da esquadria',
  texto_fundamentacao_normativa = 'O funcionamento da esquadria — abertura, fechamento e acionamento de travas de forma suave e sem esforço anormal — é requisito de uso e de segurança que atesta o correto alinhamento do quadro e a regulagem das ferragens. Aplicam-se a NBR 10821 (esquadrias externas para edificações), as instruções de regulagem do fabricante e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Abertura, fechamento e travas suaves" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Esquadria com abertura dura, fechamento incompleto ou travas que não engatam sinaliza desalinhamento ou ferragem desregulada, acelera o desgaste de roldanas, dobradiças e fechos e compromete a vedação e a segurança contra intrusão, além de gerar reclamação de uso. A permanência da condição mantém a esquadria em operação deficiente até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) testar o ciclo completo de abertura, fechamento e travamento, identificando pontos de atrito, folga ou desalinhamento; (ii) regular ferragens, roldanas e fechos e, se necessário, corrigir o alinhamento do quadro, restabelecendo a operação suave conforme o fabricante; (iii) evidenciar a correção com registro fotográfico e verificação do ciclo de funcionamento ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-06' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — manter como Crítica sempre que o vidro instalado divergir do tipo de segurança especificado (temperado/laminado) em local sujeito a risco de impacto ou queda',
  texto_fundamentacao_normativa = 'O tipo e a espessura do vidro — incluindo a exigência de vidro de segurança temperado ou laminado — devem atender à especificação de projeto conforme a NBR 7199 (vidros na construção civil: projeto, execução e aplicações), que estabelece as aplicações e os critérios de emprego dos vidros de segurança em função do risco de cada local. Aplicam-se ainda o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, e as especificações do fornecedor. O critério "Tipo/espessura (temperado/laminado) conforme NBR 7199" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Vidro em desacordo com a especificação — espessura insuficiente ou ausência do vidro de segurança exigido — reduz a resistência a impacto, cargas de vento e esforços de uso e, em caso de ruptura, pode gerar estilhaços cortantes ou queda de painel, com risco direto à integridade física dos usuários. A permanência da condição mantém instalado um vidro não conforme em local de risco até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) conferir a etiqueta/selo e a documentação do vidro instalado, confrontando tipo, classe de segurança e espessura com a NBR 7199 e o projeto; (ii) substituir o vidro não conforme pelo especificado (temperado/laminado e espessura corretos), com envidraçamento e calços adequados; (iii) evidenciar a correção com registro fotográfico do selo/certificado e do vidro instalado ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-06' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o ensaio de estanqueidade acusar infiltração em esquadria de fachada ou em ambiente crítico de umidade',
  texto_fundamentacao_normativa = 'A estanqueidade à água da esquadria, quando exigida, deve ser comprovada por ensaio de jato/aspersão d''água, verificando a ausência de penetração pelas juntas, folhas e interface com o substrato. Aplicam-se a NBR 10821 (esquadrias externas para edificações), que define métodos de verificação de estanqueidade à água, as instruções do fabricante e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Teste de jato d''água quando exigido" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Esquadria que não passa no teste de jato d''água permite a entrada de água para o interior da edificação, causando infiltração, manchas, comprometimento de acabamentos e revestimentos e degradação precoce de fixações e do próprio conjunto, com potencial de manifestação patológica recorrente na fachada. A permanência da condição mantém a esquadria permeável e sujeita a infiltração até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reexecutar o ensaio de jato/aspersão d''água nas condições exigidas, localizando os pontos de penetração; (ii) tratar as causas identificadas — refazer vedação perimetral, corrigir fixação, drenos ou junções de perfil — e submeter a esquadria a novo ensaio até a estanqueidade plena; (iii) evidenciar a correção com registro fotográfico e relatório do ensaio de estanqueidade ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-06' and item_numero = 7;

-- ED-07 (6 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a deficiência da estrutura de apoio (seção insuficiente, apoios mal contraventados ou fixações inadequadas) comprometer a estabilidade do conjunto de cobertura sob carga de vento ou peso próprio.',
  texto_fundamentacao_normativa = 'A estrutura de apoio da cobertura (trama de madeira ou estrutura metálica) deve reproduzir o dimensionamento, o esquema estrutural e o detalhamento de ligações e fixações definidos em projeto, incluindo o tratamento de proteção previsto para cada material. Para as tramas de madeira aplica-se a NBR 7190 (projeto de estruturas de madeira) e, para estruturas metálicas, a NBR 8800 (projeto de estruturas de aço e mistas), em conjunto com o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que fixam seções, espaçamentos, apoios e ancoragens. O critério "madeira/metálica com tratamento e fixações" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa, sendo o tratamento (imunização da madeira ou proteção anticorrosiva do aço) condição de durabilidade da estrutura.',
  texto_risco_consequencia = 'Estrutura de apoio fora do projeto, sem o tratamento previsto ou com fixações deficientes reduz a capacidade portante e a durabilidade da cobertura, podendo evoluir para flechas excessivas, apodrecimento/corrosão precoce e, no limite, colapso do telhado sob vento ou sobrecarga, com risco à segurança dos ocupantes e retrabalho de grande porte. A permanência da condição mantém a estrutura operando fora das premissas de projeto até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) confrontar a estrutura executada com o projeto executivo aprovado, verificando seções, espaçamentos, apoios e o tratamento de proteção de cada peça; (ii) reforçar, substituir ou refixar os elementos deficientes e completar o tratamento (imunização da madeira ou proteção anticorrosiva do aço) conforme especificação; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e, quando cabível, laudo do responsável técnico, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-07' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o recobrimento insuficiente ou a ausência de fixação abranger áreas extensas ou beirais/cumeeiras, criando risco de arrancamento de telhas e infiltração generalizada.',
  texto_fundamentacao_normativa = 'O assentamento das telhas deve seguir o recobrimento longitudinal e transversal e o esquema de fixação (ganchos, grampos, parafusos ou amarrações) indicados pelo fabricante e pelo projeto de cobertura, garantindo a estanqueidade e a resistência ao vento do pano. Na ausência de certeza quanto à norma específica do tipo de telha empregado, a fundamentação apoia-se nas instruções técnicas do fabricante, nas boas práticas de execução de coberturas e no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "longitudinal/transversal conforme fabricante" integra o plano de inspeção e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Telhas com recobrimento reduzido ou sem a fixação prescrita ficam sujeitas a infiltração por capilaridade e transbordo e ao arrancamento por sucção de vento, podendo provocar goteiras, danos a forros e instalações e queda de telhas com risco a pessoas e bens, além de retrabalho de reassentamento do pano. A permanência da condição mantém o telhado vulnerável a chuva e vento até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) medir os recobrimentos executados e conferir o esquema de fixação contra as instruções do fabricante e o projeto de cobertura; (ii) reassentar as telhas com o transpasse correto e completar as fixações faltantes, com atenção reforçada em beirais, cumeeiras e bordas expostas ao vento; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e, se necessário, teste de estanqueidade, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-07' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a inclinação executada for inferior ao mínimo do fabricante, condição que compromete o escoamento e tende a gerar infiltração recorrente em toda a área de cobertura.',
  texto_fundamentacao_normativa = 'A inclinação do telhado (caimento) deve atender ao mínimo exigido para o tipo e o modelo de telha empregados, parâmetro que condiciona a velocidade de escoamento das águas pluviais e a estanqueidade do pano. Como o valor mínimo varia conforme o produto, a fundamentação apoia-se nas instruções técnicas do fabricante da telha, nas boas práticas de execução de coberturas e no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que definem o caimento de projeto. O critério "conforme tipo de telha" integra o plano de inspeção e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Inclinação abaixo do mínimo recomendado retarda o escoamento e favorece o retorno de água por capilaridade e transbordo nos recobrimentos, resultando em infiltrações recorrentes, empoçamento e sobrecarga em regiões do telhado, com deterioração da estrutura de apoio e retrabalho de reexecução do caimento. A permanência da condição mantém o pano com escoamento deficiente até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) levantar a inclinação real do pano e confrontá-la com o mínimo do fabricante e com o caimento de projeto; (ii) corrigir o caimento por ajuste da estrutura de apoio (calços, reposicionamento de terças/ripas ou readequação do banzo), restabelecendo a inclinação especificada; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e medição da nova inclinação, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-07' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o subdimensionamento ou a falha de vedação de rufos e calhas provocar extravasamento sobre alvenarias, fachadas ou ambientes internos.',
  texto_fundamentacao_normativa = 'Rufos e calhas devem ser dimensionados para a vazão de projeto e executados com caimento, transpasse e vedação adequados, assegurando a captação e a condução das águas pluviais sem transbordamento. Aplica-se a NBR 10844 (instalações prediais de águas pluviais), que estabelece os critérios de dimensionamento e de execução de calhas e condutores, em conjunto com o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "caimento, transpasse e vedação executados" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Rufos e calhas subdimensionados, sem caimento ou com transpasses e vedações deficientes provocam transbordamento e infiltração nas interfaces telhado-parede, com manchas, deterioração de alvenarias e revestimentos, danos a instalações e comprometimento da estanqueidade da edificação, além de retrabalho de reexecução do sistema de drenagem. A permanência da condição mantém o escoamento pluvial deficiente até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) verificar o dimensionamento, o caimento, os transpasses e as vedações de rufos e calhas frente à NBR 10844 e ao projeto executivo aprovado; (ii) corrigir caimentos, refazer transpasses e selar juntas e uniões com material compatível, substituindo peças subdimensionadas quando necessário; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e ensaio de escoamento com água, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-07' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a falha de estanqueidade em parafusos ou passagens já apresentar indícios de infiltração ativa ou incidir sobre pontos críticos como cumeeiras e transições.',
  texto_fundamentacao_normativa = 'Os pontos de fixação e as passagens que atravessam o pano de cobertura (parafusos, tirefões, chaminés, tubulações e dutos) devem ser executados com arruelas de vedação e selantes que garantam a estanqueidade, impedindo a entrada de água pelas perfurações. Não havendo certeza quanto à norma específica do sistema empregado, a fundamentação apoia-se nas instruções do fabricante dos elementos de fixação e vedação, nas boas práticas de impermeabilização de coberturas e no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "vedação em parafusos/passagens" integra o plano de inspeção e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Parafusos e passagens sem vedação adequada constituem pontos preferenciais de infiltração, gerando goteiras localizadas, corrosão dos elementos de fixação, apodrecimento/oxidação da estrutura de apoio e manchas em forros e acabamentos, com deterioração progressiva e retrabalho de revedação. A permanência da condição mantém abertos os caminhos de infiltração até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) inspecionar todos os pontos de fixação e passagens, identificando arruelas ausentes, degradadas ou selantes rompidos; (ii) refazer a vedação com arruelas e selante compatíveis com o material da telha e reapertar as fixações no torque adequado, evitando esmagamento ou folga; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e verificação de estanqueidade dos pontos tratados, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-07' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — a ausência de pontos de ancoragem ou linha de vida para manutenção configura risco de queda de altura e deve ser tratada com prioridade máxima, admitindo reclassificação a Maior apenas se houver medida coletiva equivalente já implantada e comprovada.',
  texto_fundamentacao_normativa = 'A cobertura deve dispor dos pontos de ancoragem e/ou linha de vida previstos para as futuras atividades de manutenção em altura, permitindo a conexão segura de sistemas de proteção individual contra quedas. Aplica-se a NR-35 (trabalho em altura), que exige a previsão de dispositivos e sistemas de ancoragem para atividades acima de 2,00 m, em conjunto com o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que localiza e detalha os pontos de fixação. O critério "pontos de ancoragem/linha de vida instalados (NR-35)" integra o plano de inspeção e constitui requisito verificável de aceitação da etapa, com reflexo direto na segurança das operações de manutenção.',
  texto_risco_consequencia = 'A inexistência de pontos de ancoragem ou de linha de vida na cobertura impede a conexão segura dos equipamentos de proteção individual durante a manutenção, expondo os trabalhadores a queda de altura com potencial de lesões graves ou fatais, além de configurar não conformidade legal passível de embargo e responsabilização. A permanência da condição mantém a cobertura sem meio seguro de acesso e trabalho em altura até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) confrontar os pontos de ancoragem e o traçado da linha de vida executados com o projeto e com a análise de risco das atividades de manutenção previstas; (ii) instalar ou complementar os dispositivos de ancoragem e a linha de vida, com fixação estrutural adequada e, quando exigível, ensaio/certificação de carga; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e documentação técnica dos dispositivos instalados, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-07' and item_numero = 6;

-- ED-08 (6 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o subdimensionamento ou o espaçamento excessivo de perfis e pendurais comprometer a estabilidade do plano do forro ou houver risco de desprendimento sobre áreas de circulação ou permanência de pessoas',
  texto_fundamentacao_normativa = 'A estrutura de sustentação do forro (perfis, tirantes/pendurais e fixações) deve reproduzir os espaçamentos, bitolas e cargas admissíveis definidos pelo fabricante do sistema, pois é o memorial do próprio sistema que garante a distribuição de esforços e o desempenho do conjunto. O critério "Conforme fabricante do sistema" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa, confrontado com o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}} e com as instruções técnicas de montagem do fornecedor. Na ausência de norma específica que fixe esses espaçamentos, a fundamentação assenta-se no manual técnico do sistema, no projeto e nas boas práticas de montagem de forros.',
  texto_risco_consequencia = 'Estrutura ou pendurais fora do espaçamento especificado reduzem a capacidade de sustentação do forro, favorecendo flechas excessivas, ondulações, abertura de juntas e, no limite, o desprendimento de placas sobre pessoas e equipamentos. A permanência da condição mantém ativo o risco estrutural e estético até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) conferir o espaçamento, a bitola e a ancoragem de perfis e pendurais confrontando-os com o manual do fabricante e o projeto executivo aprovado; (ii) inserir os perfis e pendurais faltantes e reposicionar os fora de padrão, restabelecendo o espaçamento e a fixação especificados; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) do trecho reforçado antes do fechamento das placas, submetendo à reinspeção para encerramento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-08' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando o desnível for perceptível a olho nu, divergir das cotas de projeto ou comprometer o embutimento de luminárias, difusores e o encontro com paredes',
  texto_fundamentacao_normativa = 'O plano acabado do forro deve resultar nivelado e nas cotas de pé-direito definidas em projeto, condição verificável por nível a laser ou mangueira de nível ao longo de toda a superfície. O critério "Sem desníveis visíveis; cotas do projeto" integra o plano de inspeção e constitui requisito de aceitação, confrontado com o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que fixa as cotas de acabamento. A fundamentação apoia-se no projeto e nas boas práticas de montagem, sem invocar número de norma específico para a tolerância de nivelamento.',
  texto_risco_consequencia = 'Forro fora de nível gera desníveis e ondulações visíveis, comprometimento estético do ambiente, desalinhamento no encontro com paredes e sombras indesejadas na iluminação, além de dificultar o embutimento coordenado de luminárias e difusores. A permanência da condição perpetua o defeito de acabamento até a correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) levantar as cotas do forro com nível a laser, mapeando os pontos fora de nível em relação à cota de projeto; (ii) ajustar a regulagem dos pendurais e perfis (ou refazer o trecho, conforme o caso) até restabelecer a planicidade e as cotas especificadas; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e nova conferência de nível, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-08' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o tratamento incompleto de juntas ocorrer em áreas úmidas, forros externos ou onde a fissuração comprometer a estanqueidade ou a barreira de incêndio prevista',
  texto_fundamentacao_normativa = 'O tratamento de juntas entre placas deve ser executado com fita de reforço e massa aplicada em demãos sucessivas, com lixamento entre elas, conforme a sistemática do fabricante do sistema, de modo a obter superfície monolítica e sem fissuras. O critério "Fita + massa em demãos conforme sistema" integra o plano de inspeção e constitui requisito de aceitação, confrontado com o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}} e as instruções do fornecedor. A fundamentação assenta-se no manual do sistema e nas boas práticas de acabamento em drywall e gesso, sem invocar número de norma específico.',
  texto_risco_consequencia = 'Juntas sem fita ou com massa insuficiente tendem a fissurar e trincar com a movimentação natural das placas, expondo o desalinhamento entre chapas, prejudicando a pintura e o acabamento e, em sistemas com função corta-fogo ou acústica, comprometendo o desempenho especificado. A permanência da condição mantém latente a fissuração até o retratamento. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) inspecionar todas as juntas identificando os trechos sem fita ou com número insuficiente de demãos; (ii) reexecutar o tratamento aplicando fita de reforço e massa em demãos sucessivas com lixamento, conforme o sistema, até obter superfície uniforme e sem fissuras; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) das juntas tratadas e lixadas antes da pintura, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-08' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando o desalinhamento de requadros, sancas e negativos divergir do detalhamento arquitetônico ou comprometer a modulação de iluminação e o encontro com esquadrias',
  texto_fundamentacao_normativa = 'Requadros, sancas e juntas negativas devem ser executados alinhados, com prumo e esquadro, reproduzindo fielmente o detalhamento de projeto, pois definem a leitura arquitetônica do teto e a modulação dos elementos embutidos. O critério "Alinhados e conforme detalhamento" integra o plano de inspeção e constitui requisito de aceitação, confrontado com o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}} e os detalhes de arquitetura. A fundamentação apoia-se no projeto, nos detalhes construtivos e nas boas práticas de execução, sem invocar número de norma específico.',
  texto_risco_consequencia = 'Requadros, sancas e negativos desalinhados ou com larguras irregulares comprometem a estética do ambiente, evidenciam falta de esquadro e prumo, quebram a modulação prevista para luminárias e cortineiros e destoam do encontro com esquadrias e paredes. A permanência da condição perpetua o defeito visual até a correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) conferir com trena, prumo e linha o alinhamento, a largura e o esquadro de requadros, sancas e negativos, confrontando-os com o detalhamento de projeto; (ii) corrigir o posicionamento e a largura dos elementos (reexecução do trecho ou ajuste de perfis, conforme o caso) até atender ao detalhe aprovado; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) dos elementos alinhados, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-08' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a ausência de alçapão impedir o acesso de manutenção a equipamentos de segurança, registros de incêndio, dampers ou dispositivos que exijam inspeção periódica obrigatória',
  texto_fundamentacao_normativa = 'Devem ser previstos alçapões de acesso em todos os pontos onde o forro oculta instalações e equipamentos que demandem inspeção, operação ou manutenção (registros, dampers, caixas de passagem, válvulas, atuadores). O critério "Acesso a instalações e equipamentos" integra o plano de inspeção e constitui requisito de aceitação, confrontado com o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}} e com os projetos de instalações coordenados. A fundamentação apoia-se na compatibilização dos projetos e nas boas práticas de manutenibilidade, sem invocar número de norma específico.',
  texto_risco_consequencia = 'A falta de alçapão nos pontos de manutenção obriga a abertura destrutiva do forro para acessar registros, dampers e equipamentos embutidos, gerando custo, retrabalho e indisponibilidade das instalações, além de dificultar inspeções e o atendimento a emergências. A permanência da condição mantém inacessíveis os dispositivos até a instalação dos acessos. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) mapear, sobre os projetos de instalações compatibilizados, todos os pontos que exigem acesso e confrontá-los com os alçapões executados; (ii) instalar os alçapões faltantes nas posições e dimensões que garantam o acesso de manutenção aos equipamentos ocultos; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) dos alçapões instalados e do acesso ao equipamento correspondente, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-08' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a interface malresolvida afetar sprinklers, detecção de incêndio ou a cobertura de proteção prevista, comprometendo o desempenho dos sistemas de segurança',
  texto_fundamentacao_normativa = 'A interface do forro com as instalações — luminárias, difusores e grelhas de ar-condicionado, sprinklers e detectores — deve ser coordenada de modo que os elementos fiquem posicionados na modulação prevista, sem interferências e sem prejuízo ao funcionamento de cada sistema. O critério "Luminárias, difusores e sprinklers coordenados" integra o plano de inspeção e constitui requisito de aceitação, confrontado com o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}} e com os projetos de instalações compatibilizados. Para sprinklers e detecção de incêndio, o posicionamento deve preservar a cobertura e a sensibilidade definidas no projeto específico do sistema; a fundamentação apoia-se nesses projetos e nas boas práticas de compatibilização, sem invocar número de norma específico.',
  texto_risco_consequencia = 'Interface malresolvida gera bicos de sprinkler mal posicionados ou obstruídos, difusores desalinhados com perda de desempenho do ar-condicionado, luminárias fora da modulação e conflitos entre elementos, comprometendo estética, conforto e, sobretudo, a eficácia dos sistemas de combate e detecção de incêndio. A permanência da condição mantém o desvio de coordenação e o risco associado até a correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) confrontar o forro executado com os projetos de instalações compatibilizados, identificando os elementos fora de posição ou em conflito; (ii) reposicionar luminárias, difusores e demais terminais, e ajustar os bicos de sprinkler e detectores conforme o projeto do respectivo sistema, restabelecendo a coordenação prevista; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) dos elementos recoordenados, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-08' and item_numero = 6;

-- ED-09 (6 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a superfície apresentar umidade, pulverulência ou contaminação que comprometa a aderência de todo o sistema de pintura, exigindo remoção total das demãos aplicadas.',
  texto_fundamentacao_normativa = 'O preparo de superfície é a etapa que assegura a ancoragem e a durabilidade do sistema de pintura, devendo compreender lixamento, limpeza (remoção de poeira, gordura e partículas soltas) e aplicação de selador/fundo compatível com o substrato. Aplica-se a NBR 13245 (execução de pinturas em edificações não industriais — preparo de superfície) e a especificação técnica do fabricante do sistema adotado, bem como o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, no que define acabamentos. O critério "Lixamento, limpeza e selador/fundo conforme sistema" integra o plano de inspeção da obra e constitui requisito verificável de aceitação, condicionando a liberação das demãos subsequentes.',
  texto_risco_consequencia = 'Superfície preparada de forma inadequada compromete a aderência do sistema de pintura, favorecendo descascamento, empolamento, bolhas e destacamento precoce da tinta, com necessidade de raspagem e refazimento integral do acabamento e antecipação da manutenção da edificação. A permanência da condição mantém latente a falha de ancoragem sob as demãos já aplicadas. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) interromper a aplicação e reexecutar o preparo do substrato, com lixamento, remoção de pó e contaminantes e correção de pontos de umidade; (ii) aplicar selador/fundo compatível e na diluição indicadas pela especificação do sistema, respeitando o intervalo de secagem; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) do substrato preparado antes da pintura, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-09' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando as ondulações forem generalizadas ou visíveis sob luz rasante em áreas nobres, comprometendo o padrão de acabamento contratado.',
  texto_fundamentacao_normativa = 'A massa corrida tem função niveladora e deve resultar em superfície plana e uniforme, sem ondulações, saliências ou depressões, com lixamento entre demãos para regularização e melhora da aderência da camada seguinte. Fundamentam-se a boa técnica de execução, a especificação do fabricante da massa e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, quanto ao padrão de acabamento. O critério "Sem ondulações; lixamento entre demãos" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da regularização antes da pintura de acabamento.',
  texto_risco_consequencia = 'Massa corrida aplicada com ondulações e sem lixamento entre demãos transfere as imperfeições para a pintura final, tornando visíveis marcas, ressaltos e variações de plano sob iluminação, além de reduzir a aderência entre camadas e exigir retrabalho de nivelamento e repintura. A permanência da condição mantém o desvio de planicidade incorporado ao acabamento. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) lixar e regularizar as regiões onduladas, reaplicando massa nos pontos de depressão até obter plano uniforme; (ii) proceder ao lixamento entre demãos e à remoção do pó antes da nova camada, conferindo a superfície sob luz rasante; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) da superfície nivelada, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-09' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a insuficiência de demãos deixar o substrato ou a cor de fundo aparente, caracterizando cobertura incompleta e descumprimento do sistema especificado.',
  texto_fundamentacao_normativa = 'O número de demãos é parâmetro do sistema de pintura e deve assegurar cobertura total, uniformidade de cor e a espessura de película necessária ao desempenho e à durabilidade previstos. Aplicam-se a especificação/ficha técnica do fabricante do sistema adotado, que fixa número mínimo de demãos, rendimento, diluição e intervalos de secagem, e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Cobertura total conferida contra a especificação" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Aplicação de demãos em número inferior ao especificado resulta em cobertura incompleta, transparência do fundo, variação de tonalidade e película com espessura insuficiente, reduzindo a proteção do substrato e a vida útil da pintura, com necessidade de demãos adicionais e reinspeção. A permanência da condição mantém a área com desempenho abaixo do especificado. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) conferir o número de demãos aplicadas contra a especificação/ficha técnica do sistema e identificar as áreas com cobertura insuficiente; (ii) aplicar as demãos complementares necessárias, respeitando diluição, rendimento e intervalo de secagem, até obter cobertura e tonalidade uniformes; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) das áreas concluídas, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-09' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando manchas, escorridos ou marcas de retoque forem extensos ou ocorrerem em fachadas e áreas de destaque, comprometendo a aceitação visual do acabamento.',
  texto_fundamentacao_normativa = 'A uniformidade de acabamento reflete a correta aplicação da tinta, exigindo película homogênea, sem manchas, escorridos, sobreposições visíveis ou marcas de retoque, resultado de técnica adequada de aplicação e de condições ambientais controladas. Fundamentam-se a boa técnica de execução, a especificação do fabricante quanto a diluição e método de aplicação, e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, quanto ao padrão estético. O critério "Sem manchas, escorridos ou marcas de retoque" integra o plano de inspeção da obra e constitui requisito verificável de aceitação final.',
  texto_risco_consequencia = 'Acabamento com manchas, escorridos e marcas de retoque compromete a aparência e a homogeneidade da pintura, indica falhas de aplicação e diluição, gera rejeição visual pela fiscalização e pelo cliente e demanda lixamento e repintura das áreas afetadas. A permanência da condição mantém o defeito estético aparente na entrega. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) identificar e lixar as regiões com escorridos, manchas ou marcas de retoque, removendo o excesso de material; (ii) reaplicar a demão de acabamento em pano inteiro, com diluição e técnica adequadas e em condições ambientais favoráveis, evitando emendas visíveis; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) do acabamento uniforme, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-09' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando houver dano efetivo a esquadrias, pisos, vidros ou ferragens por respingos ou tinta aderida, exigindo limpeza especializada ou substituição de componentes.',
  texto_fundamentacao_normativa = 'A proteção de superfícies adjacentes é medida preventiva de execução que resguarda esquadrias, pisos, vidros, ferragens e demais elementos já instalados contra respingos, escorridos e manchas de tinta, mediante mascaramento com fitas, lonas e proteções apropriadas. Fundamenta-se nas boas práticas de execução e no cuidado com a preservação de serviços concluídos, em coerência com o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, e seus acabamentos. O critério "Esquadrias, pisos e ferragens protegidos" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da frente de pintura.',
  texto_risco_consequencia = 'A ausência de proteção das superfícies adjacentes expõe esquadrias, pisos, vidros e ferragens a respingos e manchas de tinta de difícil remoção, podendo danificar acabamentos concluídos e gerar custos de limpeza, recuperação ou substituição de componentes, além de conflitos entre etapas. A permanência da condição mantém os elementos vizinhos sob risco contínuo de sujidade durante a pintura. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) instalar as proteções adequadas (fitas de mascaramento, lonas e coberturas) sobre esquadrias, pisos, vidros e ferragens antes de retomar a aplicação; (ii) remover respingos e manchas já existentes com produto e técnica compatíveis, sem danificar os elementos protegidos; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) das superfícies protegidas e limpas, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-09' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando for constatada tinta divergente da especificação, fora de validade ou de procedência não comprovada aplicada na obra, exigindo remoção e refazimento.',
  texto_fundamentacao_normativa = 'A conformidade da tinta assegura o desempenho, a cor e a durabilidade previstos, exigindo verificação de marca, linha, cor e validade do lote frente à especificação e à ficha técnica do produto, com rastreabilidade por embalagem e nota fiscal. Fundamentam-se a especificação de acabamentos do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, e a documentação técnica do fabricante, que definem o produto aprovado e suas condições de uso. O critério "Marca/linha/cor e validade do lote" integra o plano de inspeção da obra e constitui requisito verificável de aceitação do material antes e durante a aplicação.',
  texto_risco_consequencia = 'Emprego de tinta em desacordo com a especificação, com cor divergente ou lote fora de validade, resulta em desempenho e durabilidade inferiores, variação de tonalidade, falhas de cura e cobertura e não atendimento ao padrão contratado, podendo exigir remoção e nova pintura com o produto correto. A permanência da condição mantém material não conforme incorporado ao acabamento. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) conferir marca, linha, cor e validade do lote nas embalagens frente à especificação e à ficha técnica, retendo os produtos não conformes; (ii) substituir a tinta divergente ou vencida por material aprovado e, onde já aplicada, remover e repintar com o produto especificado; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) das embalagens e da nota fiscal do lote aprovado, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-09' and item_numero = 6;

-- ED-10 (7 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se houver frente de serviço em altura em andamento sem projeto de fachada e ART formalizados, ou rebaixar a Menor se a ART existir e apenas a via impressa/revisão vigente não estiver disponível na frente.',
  texto_fundamentacao_normativa = 'A execução da fachada deve ser regida por projeto específico sob responsabilidade de profissional habilitado, formalizada por Anotação de Responsabilidade Técnica (ART) nos termos da Lei nº 6.496/1977, mantida disponível na frente de serviço em sua revisão vigente. A existência da ART e do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, é condição para a rastreabilidade da responsabilidade técnica e para a correta execução dos revestimentos, ancoragens e detalhes de fachada. O critério "Revisão vigente na frente" integra o plano de inspeção da obra e constitui requisito verificável de aceitação, assegurando que a equipe execute a partir do documento correto e atualizado.',
  texto_risco_consequencia = 'A ausência do projeto de fachada com ART na frente, ou a circulação de revisão superada, permite execução divergente do projeto e sem cobertura de responsabilidade técnica, favorecendo erros de especificação, retrabalho de revestimento e passivo legal por serviço não amparado por profissional habilitado. Enquanto persistir, os serviços de fachada seguem sendo executados sem base documental controlada. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) disponibilizar na frente de serviço o projeto de fachada em sua revisão vigente e a respectiva ART, confirmando o registro ativo do responsável técnico; (ii) recolher e substituir eventuais vias de revisão superada em circulação, atualizando o controle de documentos da obra; (iii) evidenciar a regularização com registro fotográfico ({{evidencia_foto_correcao}}) da via vigente na frente e cópia da ART, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-10' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — trata-se de sistema de acesso e trabalho em altura suspenso; manter Crítica sempre que houver não conformidade em projeto, ancoragens ou inspeções de balancins/andaime fachadeiro, com paralisação imediata do serviço até a regularização.',
  texto_fundamentacao_normativa = 'Balancins e andaimes fachadeiros são sistemas de acesso e trabalho em altura cuja concepção, montagem, ancoragem e inspeção devem observar a NR-18 e a NR-35, além do projeto/dimensionamento específico do sistema e das interfaces de segurança do trabalho ST-06/ST-08 previstas para a obra. As ancoragens, os pontos de fixação e as inspeções periódicas garantem a estabilidade e a integridade do conjunto sob carga e sob a ação do vento. O critério "Projeto, ancoragens e inspeções (interface ST-06/ST-08)" integra o plano de inspeção e constitui requisito verificável de aceitação, condicionando a liberação do sistema para uso.',
  texto_risco_consequencia = 'A operação de balancins ou andaime fachadeiro sem projeto, com ancoragens deficientes ou sem inspeção registrada expõe os trabalhadores a queda de altura e ao colapso do sistema, com risco direto de acidente grave ou fatal, além de queda de materiais sobre áreas inferiores. Enquanto a condição persistir, cada ciclo de uso do equipamento reincide na exposição ao risco de vida. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) paralisar o uso do sistema e conferir o projeto/dimensionamento, os pontos de ancoragem e a integridade estrutural do balancim/andaime, confrontando com a NR-18, a NR-35 e as interfaces ST-06/ST-08; (ii) corrigir ancoragens, fixações e componentes reprovados e formalizar a inspeção com liberação assinada por profissional habilitado antes de novo uso; (iii) evidenciar a regularização com registro fotográfico ({{evidencia_foto_correcao}}) das ancoragens e a ficha/checklist de inspeção assinada, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-10' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando houver revestimento aplicado sem a tela/ponte de aderência exigida em projeto ou reprovação nos ensaios de aderência, pelo risco de desplacamento em fachada; rebaixar a Menor se pendente apenas o registro do ensaio em trecho já executado conforme.',
  texto_fundamentacao_normativa = 'A aderência do revestimento de fachada deve ser assegurada pelo preparo de base e, onde exigido em projeto, pela aplicação de telas ou pontes de aderência, com verificação por ensaio de resistência de aderência à tração conforme a NBR 13528 (citada no critério do item) e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. A ancoragem do revestimento ao substrato é o que impede o desplacamento ao longo da vida útil da fachada. O critério "Telas/pontes de aderência onde exigido; ensaios NBR 13528" integra o plano de inspeção e constitui requisito verificável de aceitação da etapa de revestimento.',
  texto_risco_consequencia = 'Revestimento aplicado sem tela/ponte de aderência onde exigido, ou sem comprovação por ensaio, tende ao descolamento e desplacamento em fachada, gerando queda de material sobre áreas de circulação inferiores, risco a terceiros e necessidade de recomposição de grandes panos de revestimento. A permanência da condição mantém ativo o risco de desplacamento até a efetiva verificação e correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) identificar os trechos executados sem a tela/ponte de aderência prevista e realizar/registrar os ensaios de aderência à tração conforme a NBR 13528; (ii) corrigir os trechos reprovados com remoção e reaplicação do revestimento sobre base devidamente preparada e com a ponte de aderência exigida em projeto; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e os laudos de ensaio de aderência, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-10' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se a ausência ou o posicionamento incorreto da junta puder induzir fissuração generalizada e infiltração na fachada; rebaixar a Menor se apenas o acabamento/selante estiver pendente em junta já posicionada conforme projeto.',
  texto_fundamentacao_normativa = 'As juntas de movimentação absorvem as deformações de origem térmica e higroscópica do revestimento e da estrutura, devendo ser executadas na posição, na largura e com o selante definidos no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, e nas especificações de projeto. O correto posicionamento e o preenchimento com selante elástico compatível preservam a estanqueidade e evitam a concentração de tensões no revestimento. O critério "Posição e selante conforme projeto" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da fachada.',
  texto_risco_consequencia = 'Juntas de movimentação ausentes, mal posicionadas ou com selante inadequado impedem a acomodação das deformações da fachada, provocando fissuração do revestimento, perda de estanqueidade e infiltração, com deterioração progressiva e retrabalho de recomposição. Enquanto não corrigida, a condição mantém a fachada sujeita a fissuração e entrada de água. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) conferir a posição, a largura e o traçado das juntas de movimentação em relação ao projeto e às especificações, identificando ausências ou desvios; (ii) executar ou reposicionar as juntas e aplicar o selante elástico especificado sobre substrato limpo e com fundo de junta adequado, restabelecendo o atendimento ao projeto; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) das juntas executadas e seladas, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-10' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a ausência de lacrimal/caimento estiver provocando escorrimento e manchamento sistemático ou infiltração em vãos e esquadrias abaixo do peitoril/pingadeira.',
  texto_fundamentacao_normativa = 'Peitoris e pingadeiras devem possuir projeção (aba) com lacrimal (goteira) na face inferior e caimento voltado para fora, de modo a afastar a água da face da fachada e das esquadrias, conforme detalhamento das especificações de projeto e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, e as boas práticas de estanqueidade de fachada. O lacrimal interrompe o escorrimento por capilaridade na face inferior da peça. O critério "Lacrimal/caimento impedindo escorrimento" integra o plano de inspeção da obra e constitui requisito verificável de aceitação do detalhe de fachada.',
  texto_risco_consequencia = 'Peitoris e pingadeiras sem projeção, sem lacrimal ou com caimento invertido conduzem a água de volta à face da fachada e às esquadrias, gerando escorrimento, manchamento, deterioração do revestimento e infiltração pelos vãos, com necessidade de recomposição estética e de reparos de estanqueidade. Enquanto persistir, cada chuva reincide no escorrimento e no acúmulo de umidade sobre a fachada. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) verificar em peitoris e pingadeiras a existência de projeção, do lacrimal na face inferior e do caimento para fora, confrontando com o detalhe de projeto; (ii) corrigir as peças reprovadas, refazendo a projeção/pingadeira com lacrimal e caimento adequados e reassentamento com vedação nas juntas; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) do detalhe do lacrimal e do caimento executados, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-10' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — trata-se de proteção coletiva contra queda de materiais e pessoas durante serviço em altura; manter Crítica e paralisar as frentes protegidas por bandeja enquanto a proteção estiver ausente, incompleta ou danificada.',
  texto_fundamentacao_normativa = 'As bandejas (plataformas) de proteção são dispositivos de proteção coletiva exigidos pela NR-18 durante a execução de serviços em altura na periferia da edificação, destinadas a conter a queda de materiais e a amparar a queda de pessoas. Sua instalação, dimensões e pontos de fixação devem atender à NR-18 e às condições da obra ao longo de toda a execução da fachada. O critério "Conforme NR-18 durante a execução" integra o plano de inspeção e constitui requisito verificável de liberação da frente de trabalho em altura.',
  texto_risco_consequencia = 'A ausência, a instalação incompleta ou a remoção prematura das bandejas de proteção expõe trabalhadores e terceiros à queda de materiais e ferramentas das frentes superiores e à queda de pessoas da periferia, com risco direto de acidente grave ou fatal. Enquanto a proteção não for restabelecida, toda atividade nas frentes superiores mantém ativo o risco sobre as áreas inferiores. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) paralisar as frentes em altura desprotegidas e verificar a presença, o posicionamento e a fixação das bandejas de proteção conforme a NR-18 e as condições da obra; (ii) instalar ou completar as bandejas primárias e secundárias faltantes e corrigir fixações e elementos danificados antes de liberar os serviços superiores; (iii) evidenciar a regularização com registro fotográfico ({{evidencia_foto_correcao}}) das bandejas instaladas e fixadas, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-10' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o mapeamento por percussão indicar áreas ocas extensas ou concentradas em regiões de circulação/periferia, pelo risco de desplacamento; rebaixar a Menor se pendente apenas o registro formal do mapeamento em fachada já percutida e sem ocos relevantes.',
  texto_fundamentacao_normativa = 'A inspeção final por percussão (teste do som ôco) verifica a integridade da aderência do revestimento concluído, identificando e mapeando áreas ocas passíveis de desplacamento antes da entrega da fachada, conforme as boas práticas de recebimento de revestimento e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, e o plano de inspeção da obra. O registro do mapeamento das áreas ocas é a evidência objetiva do estado de aderência da fachada. O critério "Mapeamento de áreas ocas registrado" integra o plano de inspeção e constitui requisito verificável de aceitação final do revestimento.',
  texto_risco_consequencia = 'A entrega da fachada sem inspeção por percussão e sem o mapeamento das áreas ocas deixa passar regiões com aderência comprometida, que evoluem para desplacamento e queda de revestimento sobre áreas de circulação e terceiros ao longo do uso, com risco a pessoas e recomposição onerosa. Enquanto o mapeamento não for realizado e tratado, permanecem ocultas as áreas ocas passíveis de queda. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) executar a percussão sistemática dos panos de fachada e registrar o mapeamento das áreas ocas identificadas em planta/croqui; (ii) tratar os pontos mapeados com remoção e reaplicação do revestimento nas regiões reprovadas, seguidas de nova percussão para confirmação; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e o mapa de áreas ocas atualizado após tratamento, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-10' and item_numero = 7;

-- ED-11 (6 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o prumo, as cotas ou as dimensões internas do poço excederem as tolerâncias do desenho do fabricante a ponto de inviabilizar a instalação das guias, o curso livre do carro ou as folgas de segurança de topo e de fosso.',
  texto_fundamentacao_normativa = 'O poço e a prumada constituem a interface civil que recebe todo o conjunto de transporte vertical e devem reproduzir fielmente o desenho de poço (hoistway) fornecido pelo fabricante, condição aferida por medição de prumo e conferência topográfica de cotas. As dimensões internas, o esquadro, o prumo das paredes e as cotas de fosso e de última parada são dados vinculantes do fabricante e do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, dos quais dependem as folgas normativas de segurança e o correto assentamento de guias, contrapesos e amortecedores. O critério "Dimensões, prumo e cotas conforme desenho do fabricante" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa civil que antecede a montagem eletromecânica.',
  texto_risco_consequencia = 'Poço executado fora do prumo ou das dimensões do desenho do fabricante compromete o assentamento das guias e as folgas de segurança de topo e de fosso, podendo exigir demolição parcial, reforço estrutural ou reprojeto da instalação, com sobrecusto, atraso de cronograma e recusa de montagem pelo fabricante. A permanência da condição mantém ativo o desvio geométrico e bloqueia o início da montagem eletromecânica. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reconferir por prumo e por levantamento topográfico as dimensões internas, o esquadro e as cotas de fosso e de última parada, confrontando com o desenho de poço do fabricante e com o projeto executivo aprovado; (ii) corrigir a geometria do poço (regularização de paredes, ajuste de cotas ou reforço, conforme o caso), restabelecendo o atendimento às tolerâncias do fabricante; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e novo relatório de medição, submetendo à reinspeção e à liberação do fabricante para o fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-11' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — risco de queda de altura em vão de prumada aberto; reduzir a Maior somente após a instalação de fechamento provisório íntegro, resistente e sinalizado, e reclassificar conforme a exposição de trabalhadores no entorno.',
  texto_fundamentacao_normativa = 'Os vãos da prumada e as aberturas de pavimento configuram, durante a obra, risco de queda de altura e de queda de materiais, motivo pelo qual devem permanecer protegidos por fechamentos provisórios resistentes e sinalizados enquanto o transporte vertical não estiver concluído e liberado. Aplica-se a NR-18, que trata das medidas de proteção contra quedas em aberturas e vãos nos canteiros de obra, complementada pelo plano de segurança da obra e pelo projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Fechamentos provisórios conforme NR-18" integra o plano de inspeção e constitui requisito verificável de proteção coletiva na frente de serviço.',
  texto_risco_consequencia = 'Vão de prumada desprotegido ou com fechamento provisório frágil expõe trabalhadores e terceiros a queda de altura e a queda de objetos, com potencial de acidente grave ou fatal, além de embargo da frente de serviço e responsabilização. A permanência da condição mantém o risco ativo enquanto houver circulação no entorno do vão. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) isolar e sinalizar imediatamente o entorno do vão, interditando a circulação até a regularização; (ii) instalar ou recompor fechamento provisório resistente e fixado, dimensionado para conter pessoas e materiais, conforme a NR-18 e o plano de segurança da obra; (iii) evidenciar a proteção instalada com registro fotográfico ({{evidencia_foto_correcao}}) e inspeção de conformidade, submetendo à reinspeção para o fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-11' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o desalinhamento das guias ou a ausência de torque especificado nas fixações comprometer a estabilidade do trilho, o guiamento do carro e do contrapeso ou a atuação do freio de segurança.',
  texto_fundamentacao_normativa = 'As guias constituem o trilho de deslocamento do carro e do contrapeso e devem ser fixadas com o alinhamento, o espaçamento de suportes e o torque de aperto definidos no manual de montagem do fabricante, verificados por instrumento (prumo, gabarito e torquímetro). O alinhamento e o torque das fixações garantem a rigidez do conjunto e a superfície de referência sobre a qual atuam o guiamento e o freio de segurança, sendo parâmetros vinculados às especificações do fabricante e ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Alinhamento e torque das fixações" integra o plano de inspeção e constitui requisito verificável de aceitação da montagem mecânica.',
  texto_risco_consequencia = 'Guias desalinhadas ou com fixações sem o torque especificado geram vibração, desgaste prematuro, ruído e trepidação no deslocamento e, no limite, falha de guiamento e atuação irregular do freio de segurança, com risco ao usuário e necessidade de remontagem. A permanência da condição mantém o desvio mecânico e impede a aprovação dos ensaios subsequentes. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reconferir o alinhamento e o prumo das guias com gabarito e verificar o torque de todas as fixações com torquímetro aferido, confrontando com o manual de montagem do fabricante; (ii) corrigir o alinhamento e reapertar ou substituir as fixações fora de especificação, reposicionando suportes conforme necessário; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e planilha de torque e alinhamento, submetendo à reinspeção para o fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-11' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica na ausência de equipe credenciada pelo fabricante ou de ART de instalação recolhida antes do início da montagem, situação que descaracteriza a responsabilidade técnica e a garantia do equipamento.',
  texto_fundamentacao_normativa = 'A montagem do transporte vertical envolve risco eletromecânico e de queda e deve ser executada por empresa e equipe credenciadas pelo fabricante, sob responsabilidade técnica formalizada por Anotação de Responsabilidade Técnica (ART) de instalação registrada no CREA em nome do profissional habilitado, conforme a legislação profissional aplicável. O credenciamento assegura o cumprimento do procedimento de montagem do fabricante e a manutenção da garantia; a ART individualiza a responsabilidade técnica exigida pela boa prática e pelo projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Equipe credenciada pelo fabricante; ART de instalação" integra o plano de inspeção e constitui requisito documental verificável de habilitação da execução.',
  texto_risco_consequencia = 'Montagem executada por equipe não credenciada ou sem ART de instalação retira a responsabilidade técnica formal, pode anular a garantia do fabricante e aumenta a probabilidade de erros de montagem com risco ao usuário, além de comprometer a liberação legal do equipamento para uso. A permanência da condição mantém a instalação em situação irregular de habilitação e responsabilidade. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) comprovar o credenciamento da empresa e da equipe junto ao fabricante, apresentando os documentos de habilitação; (ii) providenciar e recolher a ART de instalação em nome do profissional habilitado, vinculando-a formalmente à obra antes da continuidade dos serviços; (iii) evidenciar a regularização com registro fotográfico da frente de montagem ({{evidencia_foto_correcao}}) e cópia dos documentos de credenciamento e da ART, submetendo à reinspeção para o fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-11' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — os ensaios de freio, fim de curso e nivelamento de parada verificam dispositivos de segurança de vida; manter Crítica enquanto qualquer ensaio não for aprovado e não reduzir a classificação sem novo ensaio conforme.',
  texto_fundamentacao_normativa = 'Os ensaios de segurança verificam o funcionamento do freio, dos dispositivos de fim de curso e do nivelamento de parada, que são funções de segurança determinantes para a operação sem risco ao usuário, e devem ser executados e aprovados conforme o procedimento de comissionamento do fabricante antes de qualquer liberação. A comprovação por ensaio funcional documentado é a evidência de que os dispositivos atuam nas condições previstas, requisito decorrente das especificações do fabricante, das boas práticas de comissionamento e do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Freios, fim de curso e nivelamento de parada" integra o plano de inspeção e constitui requisito verificável de aceitação funcional da instalação.',
  texto_risco_consequencia = 'Instalação sem ensaios de freio, fim de curso e nivelamento aprovados pode operar com falha de frenagem, ultrapassagem de curso ou desnível na parada, expondo o usuário a queda, prensamento e acidente grave ou fatal, além de impedir a liberação legal do equipamento. A permanência da condição mantém a instalação sem comprovação de segurança funcional. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) executar ou repetir os ensaios de freio, de atuação dos fins de curso e de nivelamento de parada conforme o procedimento de comissionamento do fabricante, com registro dos parâmetros medidos; (ii) corrigir os ajustes ou substituir os componentes reprovados e reensaiar até a aprovação integral; (iii) evidenciar os ensaios aprovados com registro fotográfico ({{evidencia_foto_correcao}}) e os respectivos relatórios de teste assinados, submetendo à reinspeção para o fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-11' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se a instalação for liberada ao uso sem os relatórios de teste aprovados ou sem o termo de liberação do fabricante; reduzir a Observação apenas quando faltar documento de caráter cadastral sem impacto na comprovação dos ensaios.',
  texto_fundamentacao_normativa = 'A liberação para uso deve estar amparada por documentação completa e rastreável, reunindo os relatórios de teste aprovados, o termo de liberação do fabricante e os registros de responsabilidade técnica, que evidenciam a conformidade da montagem e a aprovação dos ensaios de segurança. Essa documentação é a base formal que autoriza a entrada em operação e a transferência da instalação, constituindo requisito das boas práticas de comissionamento e do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Relatórios de teste e liberação para uso" integra o plano de inspeção e constitui requisito documental verificável para o encerramento da etapa.',
  texto_risco_consequencia = 'Liberação para uso sem a documentação completa impede comprovar a aprovação dos ensaios e a responsabilidade técnica da instalação, expondo a obra e o operador a responsabilização e a colocar em operação um equipamento sem evidência formal de segurança. A permanência da condição mantém a instalação sem rastreabilidade documental de liberação. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reunir e conferir os relatórios de teste aprovados, o termo de liberação do fabricante e os registros de responsabilidade técnica, identificando as pendências documentais; (ii) providenciar a emissão ou a complementação dos documentos faltantes, vinculando-os à instalação e ao equipamento; (iii) evidenciar a regularização com registro fotográfico do dossiê e da instalação liberada ({{evidencia_foto_correcao}}) e a juntada da documentação completa, submetendo à reinspeção para o fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-11' and item_numero = 6;

-- ED-12 (7 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando não houver projeto de formas e cimbramento ou este estiver sem ART, pois a etapa de concretagem depende de escoramento tecnicamente responsabilizado',
  texto_fundamentacao_normativa = 'O projeto de fôrmas e cimbramento deve estar disponível na frente de serviço, devidamente dimensionado e acompanhado da respectiva Anotação de Responsabilidade Técnica (ART), instrumento que vincula a responsabilidade profissional pelo dimensionamento e pela segurança do sistema provisório. Aplicam-se a NBR 15696 (fôrmas e escoramentos para estruturas de concreto — projeto, dimensionamento e procedimentos executivos) e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Dimensionado e com ART" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa, condicionando a liberação das atividades subsequentes de armação e concretagem.',
  texto_risco_consequencia = 'A execução do escoramento sem projeto dimensionado e sem ART transfere para a obra decisões estruturais de responsabilidade do projetista, deixando o sistema provisório sem lastro técnico verificável e expondo a estrutura ao risco de colapso do cimbramento durante a concretagem, com potencial de acidente grave e perda total da peça em execução. A permanência da condição mantém a etapa sem cobertura de responsabilidade técnica até a efetiva regularização. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) providenciar o projeto de fôrmas e cimbramento dimensionado, disponibilizando-o na frente de serviço em cópia controlada e vinculado ao projeto executivo aprovado; (ii) emitir e anexar a ART do responsável técnico pelo dimensionamento do sistema; (iii) evidenciar a disponibilização do projeto e da ART com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-12' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o desvio de espaçamento, contraventamento ou apoios comprometer a estabilidade do cimbramento sob carga de concretagem',
  texto_fundamentacao_normativa = 'O escoramento executado deve reproduzir fielmente o projeto de cimbramento quanto a espaçamento das escoras, contraventamento e condição dos apoios, elementos que garantem a estabilidade do conjunto e a correta transmissão das cargas de fôrma, concreto fresco e sobrecarga de execução. Aplicam-se a NBR 15696 (fôrmas e escoramentos para estruturas de concreto) e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Espaçamento, contraventamento e apoios" integra o plano de inspeção e constitui requisito verificável de aceitação antes da liberação para concretagem.',
  texto_risco_consequencia = 'Escoramento com espaçamento fora do projeto, contraventamento ausente ou apoios em base inadequada reduz a capacidade de carga e a estabilidade lateral do cimbramento, podendo provocar recalques, deformações excessivas da peça, deslocamento das escoras ou colapso durante a concretagem, com risco à integridade dos trabalhadores e à estrutura. A permanência da condição mantém ativo o risco de instabilidade do sistema provisório até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) conferir e ajustar o espaçamento das escoras e a malha de contraventamento ao projeto de cimbramento, corrigindo elementos faltantes ou mal posicionados; (ii) verificar e regularizar os apoios (bases niveladas, calços adequados e superfície com capacidade de suporte), eliminando apoios em terreno mole ou improvisado; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção do sistema antes de liberar a concretagem para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-12' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a retirada ou remanejamento de escoras ocorrer sem seguir o plano de reescoramento, expondo pavimentos inferiores a sobrecarga não prevista',
  texto_fundamentacao_normativa = 'O reescoramento deve seguir o plano estabelecido para cada pavimento, mantendo a redistribuição controlada de cargas entre lajes recém-concretadas e pavimentos inferiores enquanto o concreto ainda não atingiu resistência plena. Aplicam-se a NBR 14931 (execução de estruturas de concreto) e a NBR 15696 (fôrmas e escoramentos), além do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Plano de reescoramento por pavimento seguido" integra o plano de inspeção e constitui requisito verificável de aceitação, condicionando a sequência de desforma e reescoramento entre pavimentos.',
  texto_risco_consequencia = 'A ausência ou o descumprimento do plano de reescoramento faz com que lajes jovens recebam carga superior à sua resistência disponível na idade, e transfere esforços não previstos aos pavimentos inferiores, podendo gerar fissuração, deformação permanente ou colapso progressivo da estrutura em execução. A permanência da condição mantém ativa a sobrecarga sobre elementos ainda em cura até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) resgatar e aplicar o plano de reescoramento por pavimento, reinstalando as escoras de reescoramento nas posições e quantidades previstas; (ii) confrontar a idade e a resistência do concreto de cada laje com a sequência de retirada e reposição de escoras, corrigindo eventuais pavimentos desescorados prematuramente; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e registrar a conformidade com o plano, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-12' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a ausência de contraflecha prevista resultar em flecha final aparente ou fora dos limites de serviço da peça',
  texto_fundamentacao_normativa = 'As contraflechas previstas no projeto estrutural devem ser aplicadas na montagem das fôrmas, compensando antecipadamente as deformações de longo prazo (flechas) das lajes e vigas, de modo que a peça atinja a geometria final de projeto após a atuação das cargas permanentes. A referência é o projeto estrutural e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que definem os valores e os locais de contraflecha; os limites de deslocamento a serem atendidos derivam dos estados-limite de serviço do projeto de concreto armado. O critério "Conforme projeto estrutural" integra o plano de inspeção e constitui requisito verificável de aceitação da montagem das fôrmas.',
  texto_risco_consequencia = 'A não aplicação das contraflechas previstas faz a peça acumular a flecha total sem compensação, resultando em deslocamentos verticais aparentes, acúmulo de água em lajes de cobertura, fissuração de revestimentos e alvenarias apoiadas e comprometimento do desempenho em serviço, muitas vezes só perceptível após a desforma, quando a correção é onerosa. A permanência da condição consolida a deformação não compensada na geometria definitiva da peça. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reconferir no projeto estrutural os valores e locais de contraflecha aplicáveis ao trecho e ajustar a montagem das fôrmas antes da concretagem; (ii) quando a peça já estiver concretada sem a contraflecha prevista, submeter a divergência ao projetista estrutural para avaliação da flecha resultante e definição de tratamento; (iii) evidenciar a correção ou a avaliação com registro fotográfico ({{evidencia_foto_correcao}}) e medição de nível, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-12' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a desforma ocorrer antes do prazo mínimo ou sem liberação do projetista, expondo a peça a esforços com resistência insuficiente',
  texto_fundamentacao_normativa = 'Os prazos de desforma devem ser respeitados de acordo com a evolução da resistência do concreto e a liberação do projetista, assegurando que a retirada de fôrmas e escoras só ocorra quando a peça tiver capacidade estrutural para suportar o peso próprio e as cargas de execução. Aplica-se a NBR 14931 (execução de estruturas de concreto), conforme o próprio critério do item, complementada pelo projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "NBR 14931 / liberação do projetista" integra o plano de inspeção e constitui requisito verificável de aceitação, condicionando a operação de desforma à autorização técnica.',
  texto_risco_consequencia = 'A desforma antecipada, antes de o concreto atingir a resistência necessária ou sem a liberação do projetista, submete a peça a esforços que ela ainda não é capaz de resistir, podendo causar fissuração, deformação excessiva, dano irreversível ou colapso do elemento estrutural. A permanência da condição mantém a peça exposta a carregamento incompatível com sua idade e resistência até a efetiva regularização. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) suspender a desforma de trechos sem comprovação de resistência ou sem liberação formal, reinstalando o escoramento onde a retirada foi indevida; (ii) confrontar os prazos e a resistência do concreto (rompimento de corpos de prova ou maturidade) com os critérios de desforma e obter a liberação do projetista antes de prosseguir; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e anexar a autorização de desforma, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-12' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a abertura executada atingir região de concentração de esforços ou de armadura principal sem anuência do projetista',
  texto_fundamentacao_normativa = 'Furos e passagens em lajes e vigas devem ser previstos em projeto ou executados somente com anuência formal do projetista estrutural, pois aberturas não aprovadas interrompem a continuidade da seção resistente e da armadura, alterando o comportamento estrutural do elemento. A fundamentação decorre do projeto estrutural e do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que localizam as passagens compatibilizadas e definem os reforços necessários. O critério "Aberturas em lajes/vigas somente com anuência do projetista" integra o plano de inspeção e constitui requisito verificável de aceitação, subordinando qualquer abertura à autorização técnica prévia.',
  texto_risco_consequencia = 'A execução de furos e passagens não aprovados corta armaduras e reduz a seção resistente em pontos não avaliados, podendo gerar fissuração, perda de capacidade de carga e comprometimento da segurança da laje ou viga, com necessidade de reforço estrutural corretivo de alto custo. A permanência da condição mantém o elemento com abertura não verificada em sua capacidade resistente até a efetiva regularização. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) interromper a abertura de novos furos não previstos e mapear as passagens já executadas fora do projeto; (ii) submeter as aberturas ao projetista estrutural para avaliação e definição de reforços ou realocação, executando os reforços aprovados; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e anexar a anuência do projetista, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-12' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a concretagem for liberada sem o checklist CV-04 correspondente, deixando a etapa de concreto sem verificação documentada',
  texto_fundamentacao_normativa = 'A interface com o checklist CV-04 deve ser aplicada a cada concretagem, garantindo que a verificação de controle do concreto (recebimento, ensaios, lançamento, adensamento e cura) seja formalmente executada e vinculada à etapa de estrutura predial. A fundamentação está no plano de inspeção e ensaios da obra, que estabelece a integração entre os checklists de forma/escoramento e de concreto, e no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Checklist de concreto executado por concretagem" constitui requisito verificável de rastreabilidade, assegurando que nenhuma concretagem seja considerada aceita sem o correspondente registro de controle do concreto.',
  texto_risco_consequencia = 'A não aplicação do checklist CV-04 por concretagem rompe a rastreabilidade do controle tecnológico do concreto, deixando lançamento, ensaios e cura sem evidência documentada e impedindo a detecção tempestiva de não conformidades de resistência ou de execução, que só apareceriam em fase avançada da obra. A permanência da condição mantém as concretagens sem verificação formal do concreto associada à estrutura até a efetiva regularização. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) vincular cada concretagem da estrutura ao respectivo checklist CV-04, resgatando os registros das concretagens já realizadas sem a interface aplicada; (ii) implementar rotina que condicione a liberação de nova concretagem ao preenchimento e arquivamento do CV-04 correspondente; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e anexar os checklists CV-04 vinculados, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-12' and item_numero = 7;

-- ED-13 (5 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando houver vazamento ativo, infiltração para elementos vizinhos ou aparelho sem funcionamento que impeça o uso da unidade.',
  texto_fundamentacao_normativa = 'A fixação e o pleno funcionamento de louças e metais são condição de aceitação da etapa de acabamento, verificada por ensaio de estanqueidade e teste de acionamento sob pressão de serviço. A instalação predial de água fria e a estanqueidade dos pontos de consumo observam a NBR 5626, e os aparelhos e metais devem atender às especificações do fabricante e ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, quanto a modelo, posicionamento e vazão. O critério "Sem vazamentos; acionamentos suaves" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da unidade.',
  texto_risco_consequencia = 'Louça ou metal com vazamento, fixação deficiente ou acionamento travado gera desperdício de água, infiltração em bancadas, forros e unidades inferiores, deterioração de acabamentos já executados e reclamação de garantia, além de comprometer o uso pretendido do ambiente. A permanência da condição mantém o ponto exposto a agravamento por umidade até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reapertar ou refixar a louça/metal e substituir vedações, guarnições ou reparos defeituosos, eliminando o vazamento na origem; (ii) reexecutar o teste de estanqueidade sob pressão de serviço e verificar a suavidade do acionamento em todos os pontos da unidade; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e resultado do reteste, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-13' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a falha de nivelamento ou de vedação permitir acúmulo/infiltração de água na estrutura de apoio ou no mobiliário embutido.',
  texto_fundamentacao_normativa = 'A bancada deve ser assentada nivelada e ter suas juntas com a parede e o entorno de cubas seladas de forma contínua, condição verificada por nível e inspeção visual da linha de rejunte/silicone. O nivelamento assegura o correto escoamento e o apoio uniforme da peça, e a vedação contínua impede a passagem de água pelas juntas, conforme as especificações de assentamento do material e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Fixação e rejunte/silicone contínuos" integra o plano de inspeção e constitui requisito verificável de aceitação do serviço.',
  texto_risco_consequencia = 'Bancada fora de nível ou com vedação interrompida permite empoçamento e a percolação de água pelas juntas, causando infiltração no suporte, apodrecimento de mobiliário embutido, manchamento e descolamento da peça, com risco à estabilidade da fixação e retrabalho de acabamento. A permanência da condição mantém a junta permeável até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) conferir o nivelamento da bancada e reposicionar/recalçar a peça e seus apoios quando necessário; (ii) remover o rejunte/silicone falho e reaplicar cordão contínuo e uniforme nas juntas de parede e no perímetro das cubas, respeitando o tempo de cura; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e nova verificação de nível e vedação, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-13' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — por se tratar de interface de estanqueidade da envoltória; rebaixar a Maior apenas quando o desvio for de acabamento e não houver caminho de infiltração para o interior.',
  texto_fundamentacao_normativa = 'Soleiras e peitoris devem ser assentados com caimento voltado para o exterior e juntas seladas, de modo a conduzir a água para fora e impedir seu retorno ao interior, condição verificada por conferência de caimento e teste de estanqueidade/estagnação. Trata-se de elemento da envoltória cujo desempenho de vedação à água é requisito de projeto, conforme as especificações de assentamento e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Caimento para fora; sem infiltração" integra o plano de inspeção e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Soleira ou peitoril com caimento invertido, sem caimento ou com junta aberta encaminha a água da chuva para o interior da edificação, provocando infiltração em vãos, umidade em paredes e pisos, manchas, descolamento de revestimentos e danos a esquadrias, com retrabalho e reclamação de garantia. A permanência da condição mantém a via de infiltração ativa a cada evento de chuva até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) corrigir o assentamento restabelecendo o caimento para o exterior da soleira/peitoril e o nível de projeto; (ii) reexecutar a selagem das juntas e a impermeabilização do rejunte, e realizar teste de estanqueidade (estagnação/aspersão de água) confirmando ausência de infiltração; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e resultado do teste, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-13' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a falha comprometer o fechamento, a segurança/privacidade ou o funcionamento da fechadura, ou impedir a operação normal da porta.',
  texto_fundamentacao_normativa = 'A porta deve operar com folgas uniformes, ferragens completas e fechadura e dobradiças reguladas, condição verificada por ensaio de abertura/fechamento e conferência das folgas em todo o perímetro. O ajuste adequado assegura o alinhamento, o funcionamento e a durabilidade do conjunto, conforme as especificações do fabricante das ferragens e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, quanto ao tipo, quantidade e posicionamento das peças. O critério "Folgas, fechaduras e dobradiças reguladas" integra o plano de inspeção e constitui requisito verificável de aceitação do serviço.',
  texto_risco_consequencia = 'Porta com folgas irregulares, ferragens faltantes ou fechadura/dobradiças desreguladas trava ou raspa no batente, não fecha ou não tranca, compromete a segurança e a privacidade do ambiente e acelera o desgaste de dobradiças e do requadro, resultando em reclamação de garantia e retrabalho. A permanência da condição mantém o desgaste progressivo do conjunto até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reajustar a folha e regular dobradiças e fechadura, restabelecendo folgas uniformes e o correto encaixe no batente; (ii) instalar as ferragens faltantes e testar abertura, fechamento e travamento em ciclos, conferindo alinhamento e ausência de atrito; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e teste de operação, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-13' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a sujeira remanescente mascarar defeitos, danificar acabamentos (resíduos de argamassa/tinta/silicone) ou inviabilizar a vistoria de entrega.',
  texto_fundamentacao_normativa = 'A limpeza fina é a etapa que deixa a unidade em condição de vistoria, com remoção de resíduos de obra, respingos e películas de vidros, louças, metais, pisos e esquadrias, condição verificada por inspeção visual do ambiente concluído. Constitui requisito de entrega previsto no plano de inspeção da obra e nas especificações do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, servindo também para expor eventuais defeitos antes da aceitação. O critério "Unidade pronta para vistoria" integra o plano de inspeção e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'A ausência de limpeza fina mantém respingos de argamassa, tinta e silicone, poeira e etiquetas sobre acabamentos, mascarando defeitos, dificultando a vistoria e podendo danificar superfícies (riscos em vidros, manchas em louças e metais) quando a remoção é feita tardiamente de forma inadequada, com retrabalho e atraso na entrega. A permanência da condição posterga a liberação da unidade até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) executar a limpeza fina de todos os ambientes, removendo resíduos, respingos, etiquetas e películas com produtos compatíveis com cada superfície; (ii) revisar vidros, louças, metais, pisos e esquadrias e registrar eventuais defeitos revelados para tratamento; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) da unidade limpa, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-13' and item_numero = 5;

-- ED-14 (5 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a ausência de roteiro padronizado resultar em unidades entregues sem verificação uniforme de pisos, paredes, esquadrias ou instalações, ou quando a falha de registro impedir a rastreabilidade das pendências.',
  texto_fundamentacao_normativa = 'A vistoria de entrega de cada unidade deve seguir roteiro padronizado que percorra sistematicamente pisos, paredes, esquadrias e instalações, assegurando que todas as unidades sejam avaliadas sob os mesmos critérios de aceitação e que os desvios fiquem documentados. O critério "Roteiro padronizado (pisos, paredes, esquadrias, instalações)" integra o plano de inspeção da obra e constitui requisito verificável de conformidade da etapa de entrega, tomando como referência de aceitação o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, e as especificações técnicas do empreendimento. Trata-se de boa prática consolidada de gestão da qualidade na construção, em que a padronização do roteiro garante uniformidade, comparabilidade e rastreabilidade das verificações.',
  texto_risco_consequencia = 'A aplicação de vistoria sem roteiro padronizado permite que itens de pisos, paredes, esquadrias ou instalações deixem de ser inspecionados em parte das unidades, entregando ao cliente defeitos não detectados, gerando reclamações pós-entrega, acionamento de garantia e retrabalho com a unidade já ocupada. A permanência da condição mantém ativo o risco de aceitação de unidades com não conformidades ocultas até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) formalizar e adotar o roteiro padronizado de vistoria por unidade, contemplando expressamente pisos, paredes, esquadrias e instalações, com campos para registro de conformidade e de pendências; (ii) reaplicar a vistoria nas unidades já verificadas sem o roteiro padrão, consolidando os resultados em formulário único; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e os checklists preenchidos e assinados, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-14' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o teste revelar vazamento, ausência de estanqueidade em gás, falta de aterramento ou falha de funcionamento elétrico que exponha o usuário a risco de incêndio, choque ou intoxicação.',
  texto_fundamentacao_normativa = 'O funcionamento das instalações de água, esgoto, elétrica e gás deve ser demonstrado e testado durante a vistoria, condição indispensável para a aceitação da unidade em condições de uso seguro. Aplicam-se a NBR 5410 (instalações elétricas de baixa tensão), a NBR 5626 (sistemas prediais de água fria), a NBR 8160 (sistemas prediais de esgoto sanitário) e a NBR 15526 (redes de distribuição interna para gases combustíveis), que estabelecem os requisitos de execução e de verificação de funcionamento e estanqueidade dessas instalações, complementadas pelo projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Água, esgoto, elétrica e gás testados na vistoria" integra o plano de inspeção e constitui requisito verificável de aceitação da etapa de entrega.',
  texto_risco_consequencia = 'A entrega de unidade sem demonstração efetiva do funcionamento das instalações pode transferir ao usuário falhas graves — vazamentos hidráulicos, obstruções de esgoto, ausência de aterramento ou de proteção elétrica e fugas de gás — com risco direto de dano material, choque elétrico, incêndio ou intoxicação, além de acionamento de garantia e responsabilização do construtor. A permanência da condição mantém ativo o risco de uso da unidade com instalações não comprovadas até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) executar e registrar os testes de funcionamento das quatro instalações — pressurização e estanqueidade da água fria, escoamento e vedação do esgoto, energização com verificação de dispositivos de proteção e aterramento no sistema elétrico, e teste de estanqueidade da rede de gás; (ii) sanar as falhas identificadas e reensaiar os pontos reprovados até plena aprovação; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e os laudos/relatórios de teste correspondentes, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-14' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando o manual não for entregue ou estiver incompleto quanto a prazos de garantia e periodicidade de manutenção, comprometendo os direitos do adquirente e a preservação do desempenho da edificação.',
  texto_fundamentacao_normativa = 'O Manual de Uso, Operação e Manutenção da edificação deve ser elaborado e entregue ao proprietário no ato da entrega da unidade, com informações sobre garantias, prazos e procedimentos de manutenção. Aplica-se a NBR 14037 (diretrizes para elaboração de manuais de uso, operação e manutenção das edificações), articulada à NBR 5674 (manutenção de edificações — requisitos para o sistema de gestão de manutenção) e ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "NBR 14037 com garantias e manutenções" integra o plano de inspeção e constitui requisito verificável de aceitação da etapa de entrega, condicionando a correta operação da edificação e a validade das garantias.',
  texto_risco_consequencia = 'A não entrega do manual, ou sua entrega incompleta, priva o usuário das instruções de uso e dos prazos e condições de garantia e manutenção, favorecendo a operação inadequada dos sistemas, a perda de garantia por manutenção negligenciada e a redução da vida útil e do desempenho da edificação, além de fragilizar a posição contratual do construtor perante o adquirente. A permanência da condição mantém ativo o risco de operação da unidade sem orientação formal até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) elaborar ou completar o Manual de Uso, Operação e Manutenção conforme a NBR 14037, contemplando descrição dos sistemas, prazos de garantia e programa de manutenção preventiva; (ii) entregar formalmente o manual ao adquirente mediante protocolo/recibo datado e assinado; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e o comprovante de entrega assinado, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-14' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando as pendências não forem registradas com prazo e responsável, ou quando a reinspeção não for agendada, permitindo que defeitos identificados fiquem sem tratamento formal e rastreável.',
  texto_fundamentacao_normativa = 'As pendências identificadas na vistoria devem ser registradas em lista assinada pelas partes, com prazo definido para saneamento e reinspeção agendada, de modo a assegurar o encerramento controlado de cada não conformidade antes da aceitação definitiva da unidade. O critério "Lista assinada pelas partes; reinspeção agendada" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa de entrega, tomando por referência o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, e as especificações do empreendimento. Trata-se de boa prática consolidada de gestão da qualidade e de rastreabilidade documental, em que o registro formal com prazo e responsável garante o efetivo tratamento e a verificação final das pendências.',
  texto_risco_consequencia = 'O registro deficiente das pendências — sem lista assinada, sem prazo ou sem reinspeção agendada — permite que defeitos identificados na entrega deixem de ser corrigidos, gerando divergência entre as partes sobre o que foi acordado, reclamações posteriores, litígio contratual e retrabalho com a unidade ocupada. A permanência da condição mantém ativo o risco de pendências não tratadas e sem rastreabilidade até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) consolidar todas as pendências da unidade em lista única, com descrição do item, prazo de saneamento e responsável, colhendo a assinatura das partes; (ii) agendar formalmente a reinspeção e executar as correções dentro do prazo pactuado, atualizando o status de cada item; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e a lista de pendências assinada com o agendamento da reinspeção, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-14' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando houver entrega de chaves sem termo assinado ou sem a documentação formalizada, expondo as partes à indefinição de responsabilidades e à ausência de marco formal de transferência da unidade.',
  texto_fundamentacao_normativa = 'A entrega da unidade deve ser formalizada por termo de entrega assinado, acompanhado da transferência das chaves e da documentação pertinente, estabelecendo o marco inequívoco de transmissão da posse e da responsabilidade sobre o imóvel. O critério "Chaves e documentação formalizadas" integra o plano de inspeção e constitui requisito verificável de aceitação e encerramento da etapa de entrega, tomando por referência o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, as especificações do empreendimento e a documentação legal de conclusão da obra. Trata-se de requisito contratual e de boa prática consolidada de formalização documental, que resguarda ambas as partes quanto ao momento e às condições da entrega.',
  texto_risco_consequencia = 'A entrega da unidade sem termo assinado e sem documentação formalizada gera indefinição sobre a data efetiva da transferência, sobre o estado da unidade na entrega e sobre a titularidade das responsabilidades por eventuais defeitos e despesas, favorecendo litígio, dificuldade de acionamento de garantias e fragilização da posição do construtor e do adquirente. A permanência da condição mantém ativo o risco de entrega sem marco formal até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) emitir o termo de entrega da unidade, com descrição do estado de aceitação, relação de chaves e documentação anexa, colhendo a assinatura das partes; (ii) formalizar a transferência das chaves e reunir a documentação obrigatória (manual, garantias e documentos legais de conclusão) em ato registrado; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e o termo de entrega assinado com os respectivos anexos, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'ED-14' and item_numero = 5;

